INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id) VALUES (
  'سورة الفاتحة مكتوبة برواية ورش عن نافع',
  '
<<< سورة الفاتحة للقراءة برواية ورش عن نافع مكتوبة كاملة بالتشكيل >>>
+++ بِسْمِ اِ۬للَّهِ اِ۬لرَّحْمَٰنِ اِ۬لرَّحِيمِ
اِ۬لْحَمْدُ لِلهِ رَبِّ اِ۬لْعَٰلَمِينَ (1) اَ۬لرَّحْمَٰنِ اِ۬لرَّحِيمِ (2) مَلِكِ يَوْمِ اِ۬لدِّينِۖ (3) إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُۖ (4) اُ۪هْدِنَا اَ۬لصِّرَٰطَ اَ۬لْمُسْتَقِيمَ (5) صِرَٰطَ اَ۬لذِينَ أَنْعَمْتَ عَلَيْهِمْ (6) غَيْرِ اِ۬لْمَغْضُوبِ عَلَيْهِمْ وَلَا اَ۬لضَّآلِّينَۖ (7)
',
  1,
  1,
  1,
  'published',
  1
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id) VALUES (
  'سورة البقرة مكتوبة برواية ورش عن نافع',
  '
<<< سورة البقرة للقراءة برواية ورش عن نافع مكتوبة كاملة بالتشكيل >>>
+++ بِسْمِ اِ۬للَّهِ اِ۬لرَّحْمَٰنِ اِ۬لرَّحِيمِ
أَلَٓمِّٓۖ ذَٰلِكَ اَ۬لْكِتَٰبُ لَا رَيْبَۖ فِيهِ هُديٗ لِّلْمُتَّقِينَ (1) اَ۬لذِينَ يُومِنُونَ بِالْغَيْبِ وَيُقِيمُونَ اَ۬لصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَۖ (2) وَالذِينَ يُومِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِالَاخِرَةِ هُمْ يُوقِنُونَ (3) أُوْلَٰٓئِكَ عَلَيٰ هُديٗ مِّن رَّبِّهِمْۖ وَأُوْلَٰٓئِكَ هُمُ اُ۬لْمُفْلِحُونَۖ (4) إِنَّ اَ۬لذِينَ كَفَرُواْ سَوَآءٌ عَلَيْهِمُۥٓ ءَآنذَرْتَهُمُۥٓ أَمْ لَمْ تُنذِرْهُمْ لَا يُومِنُونَۖ (5) خَتَمَ اَ۬للَّهُ عَلَيٰ قُلُوبِهِمْ وَعَلَيٰ سَمْعِهِمْۖ وَعَلَيٰٓ أَبْصٰ۪رِهِمْ غِشَٰوَةٞۖ وَلَهُمْ عَذَابٌ عَظِيمٞۖ (6) وَمِنَ اَ۬لنَّاسِ مَنْ يَّقُولُ ءَامَنَّا بِاللَّهِ وَبِالْيَوْمِ اِ۬لَاخِرِ وَمَا هُم بِمُومِنِينَۖ (7) يُخَٰدِعُونَ اَ۬للَّهَ وَالذِينَ ءَامَنُواْ وَمَا يُخَٰدِعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَۖ (8) فِے قُلُوبِهِم مَّرَضٞ فَزَادَهُمُ اُ۬للَّهُ مَرَضاٗۖ وَلَهُمْ عَذَابٌ اَلِيمُۢ بِمَا كَانُواْ يُكَذِّبُونَۖ (9) وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُواْ فِے اِ۬لَارْضِ قَالُوٓاْ إِنَّمَا نَحْنُ مُصْلِحُونَۖ (10) أَلَآ إِنَّهُمْ هُمُ اُ۬لْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَۖ (11) وَإِذَا قِيلَ لَهُمُۥٓ ءَامِنُواْ كَمَآ ءَامَنَ اَ۬لنَّاسُ قَالُوٓاْ أَنُومِنُ كَمَآ ءَامَنَ اَ۬لسُّفَهَآءُۖ اَ۬لَآ إِنَّهُمْ هُمُ اُ۬لسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَۖ (12) وَإِذَا لَقُواْ اُ۬لذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّاۖ وَإِذَا خَلَوِاْ اِلَيٰ شَيَٰطِينِهِمْ قَالُوٓاْ إِنَّا مَعَكُمُۥٓ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَۖ (13) اَ۬للَّهُ يَسْتَهْزِۓُ بِهِمْ وَيَمُدُّهُمْ فِے طُغْيَٰنِهِمْ يَعْمَهُونَۖ (14) أُوْلَٰٓئِكَ اَ۬لذِينَ اَ۪شْتَرَوُاْ اُ۬لضَّلَٰلَةَ بِالْهُد۪يٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُواْ مُهْتَدِينَۖ (15) ۞مَثَلُهُمْ كَمَثَلِ اِ۬لذِے اِ۪سْتَوْقَدَ نَاراٗ فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ اَ۬للَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِے ظُلُمَٰتٖ لَّا يُبْصِرُونَۖ (16) صُمُّۢ بُكْمٌ عُمْيٞ فَهُمْ لَا يَرْجِعُونَۖ (17) أَوْ كَصَيِّبٖ مِّنَ اَ۬لسَّمَآءِ فِيهِ ظُلُمَٰتٞ وَرَعْدٞ وَبَرْقٞۖ يَجْعَلُونَ أَصَٰبِعَهُمْ فِےٓ ءَاذَانِهِم مِّنَ اَ۬لصَّوَٰعِقِ حَذَرَ اَ۬لْمَوْتِۖ وَاللَّهُ مُحِيطُۢ بِالْكٰ۪فِرِينَۖ (18) يَكَادُ اُ۬لْبَرْقُ يَخْطَفُ أَبْصَٰرَهُمْۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْاْ فِيهِۖ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُواْۖ وَلَوْ شَآءَ اَ۬للَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصٰ۪رِهِمُۥٓۖ إِنَّ اَ۬للَّهَ عَلَيٰ كُلِّ شَےْءٖ قَدِيرٞۖ (19) يَٰٓأَيُّهَا اَ۬لنَّاسُ اُ۟عْبُدُواْ رَبَّكُمُ اُ۬لذِے خَلَقَكُمْ وَالذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَۖ (20) اَ۬لذِے جَعَلَ لَكُمُ اُ۬لَارْضَ فِرَٰشاٗ وَالسَّمَآءَ بِنَآءٗ وَأَنزَلَ مِنَ اَ۬لسَّمَآءِ مَآءٗ فَأَخْرَجَ بِهِۦ مِنَ اَ۬لثَّمَرَٰتِ رِزْقاٗ لَّكُمْۖ فَلَا تَجْعَلُواْ لِلهِ أَندَاداٗ وَأَنتُمْ تَعْلَمُونَۖ (21) وَإِن كُنتُمْ فِے رَيْبٖ مِّمَّا نَزَّلْنَا عَلَيٰ عَبْدِنَا فَاتُواْ بِسُورَةٖ مِّن مِّثْلِهِۦ وَادْعُواْ شُهَدَآءَكُم مِّن دُونِ اِ۬للَّهِ إِن كُنتُمْ صَٰدِقِينَۖ (22) فَإِن لَّمْ تَفْعَلُواْ وَلَن تَفْعَلُواْ فَاتَّقُواْ اُ۬لنَّارَ اَ۬لتِے وَقُودُهَا اَ۬لنَّاسُ وَالْحِجَارَةُۖ أُعِدَّتْ لِلْكٰ۪فِرِينَۖ (23) وَبَشِّرِ اِ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ اُ۬لصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٖ تَجْرِے مِن تَحْتِهَا اَ۬لَانْهَٰرُۖ كُلَّمَا رُزِقُواْ مِنْهَا مِن ثَمَرَةٖ رِّزْقاٗ قَالُواْ هَٰذَا اَ۬لذِے رُزِقْنَا مِن قَبْلُۖ وَأُتُواْ بِهِۦ مُتَشَٰبِهاٗۖ وَلَهُمْ فِيهَآ أَزْوَٰجٞ مُّطَهَّرَةٞۖ وَهُمْ فِيهَا خَٰلِدُونَۖ (24) ۞إِنَّ اَ۬للَّهَ لَا يَسْتَحْيِۦٓ أَنْ يَّضْرِبَ مَثَلاٗ مَّا بَعُوضَةٗ فَمَا فَوْقَهَاۖ فَأَمَّا اَ۬لذِينَ ءَامَنُواْ فَيَعْلَمُونَ أَنَّهُ اُ۬لْحَقُّ مِن رَّبِّهِمْۖ وَأَمَّا اَ۬لذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ اَ۬للَّهُ بِهَٰذَا مَثَلاٗۖ يُضِلُّ بِهِۦ كَثِيراٗ وَيَهْدِے بِهِۦ كَثِيراٗۖ وَمَا يُضِلُّ بِهِۦٓ إِلَّا اَ۬لْفَٰسِقِينَ (25) اَ۬لذِينَ يَنقُضُونَ عَهْدَ اَ۬للَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ اَ۬للَّهُ بِهِۦٓ أَنْ يُّوصَلَ وَيُفْسِدُونَ فِے اِ۬لَارْضِۖ أُوْلَٰٓئِكَ هُمُ اُ۬لْخَٰسِرُونَۖ (26) كَيْفَ تَكْفُرُونَ بِاللَّهِ وَكُنتُمُۥٓ أَمْوَٰتاٗ فَأَحْي۪اكُمْۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَۖ (27) هُوَ اَ۬لذِے خَلَقَ لَكُم مَّا فِے اِ۬لَارْضِ جَمِيعاٗۖ ثُمَّ اَ۪سْتَو۪يٰٓ إِلَي اَ۬لسَّمَآءِ فَسَوّ۪يٰهُنَّ سَبْعَ سَمَٰوَٰتٖۖ وَهُوَ بِكُلِّ شَےْءٍ عَلِيمٞۖ (28) وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّے جَاعِلٞ فِے اِ۬لَارْضِ خَلِيفَةٗۖ قَالُوٓاْ أَتَجْعَلُ فِيهَا مَنْ يُّفْسِدُ فِيهَا وَيَسْفِكُ اُ۬لدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيَ أَعْلَمُ مَا لَا تَعْلَمُونَۖ (29) وَعَلَّمَ ءَادَمَ اَ۬لَاسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَي اَ۬لْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِے بِأَسْمَآءِ هَٰٓؤُلَآءِ ان كُنتُمْ صَٰدِقِينَۖ (30) قَالُواْ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ إِنَّكَ أَنتَ اَ۬لْعَلِيمُ اُ۬لْحَكِيمُۖ (31) قَالَ يَٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْۖ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمَ اَقُل لَّكُمُۥٓ إِنِّيَ أَعْلَمُ غَيْبَ اَ۬لسَّمَٰوَٰتِ وَالَارْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَۖ (32) ۞وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ اِ۟سْجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبْلِيسَ أَب۪يٰ وَاسْتَكْبَرَ وَكَانَ مِنَ اَ۬لْكٰ۪فِرِينَۖ (33) وَقُلْنَا يَٰٓـَٔادَمُ اُ۟سْكُنَ اَنتَ وَزَوْجُكَ اَ۬لْجَنَّةَ وَكُلَا مِنْهَا رَغَداً حَيْثُ شِئْتُمَاۖ وَلَا تَقْرَبَا هَٰذِهِ اِ۬لشَّجَرَةَ فَتَكُونَا مِنَ اَ۬لظَّٰلِمِينَۖ (34) فَأَزَلَّهُمَا اَ۬لشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلْنَا اَ۪هْبِطُواْۖ بَعْضُكُمْ لِبَعْضٍ عَدُوّٞۖ وَلَكُمْ فِے اِ۬لَارْضِ مُسْتَقَرّٞ وَمَتَٰعٌ اِلَيٰ حِينٖۖ (35) فَتَلَقّ۪يٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيْهِۖ إِنَّهُۥ هُوَ اَ۬لتَّوَّابُ اُ۬لرَّحِيمُۖ (36) قُلْنَا اَ۪هْبِطُواْ مِنْهَا جَمِيعاٗۖ فَإِمَّا يَاتِيَنَّكُم مِّنِّے هُديٗ فَمَن تَبِعَ هُد۪ايَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۖ (37) وَالذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصْحَٰبُ اُ۬لنّ۪ارِ هُمْ فِيهَا خَٰلِدُونَۖ (38) يَٰبَنِےٓ إِسْرَآءِيلَ اَ۟ذْكُرُواْ نِعْمَتِيَ اَ۬لتِےٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُواْ بِعَهْدِےٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰيَ فَارْهَبُونِۖ (39) وَءَامِنُواْ بِمَآ أَنزَلْتُ مُصَدِّقاٗ لِّمَا مَعَكُمْ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۢ بِهِۦۖ وَلَا تَشْتَرُواْ بِـَٔايَٰتِے ثَمَناٗ قَلِيلاٗ وَإِيَّٰيَ فَاتَّقُونِۖ (40) ۞وَلَا تَلْبِسُواْ اُ۬لْحَقَّ بِالْبَٰطِلِ وَتَكْتُمُواْ اُ۬لْحَقَّ وَأَنتُمْ تَعْلَمُونَۖ (41) وَأَقِيمُواْ اُ۬لصَّلَوٰةَ وَءَاتُواْ اُ۬لزَّكَوٰةَ وَارْكَعُواْ مَعَ اَ۬لرَّٰكِعِينَۖ (42) أَتَامُرُونَ اَ۬لنَّاسَ بِالْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ اَ۬لْكِتَٰبَۖ أَفَلَا تَعْقِلُونَۖ (43) وَاسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَوٰةِۖ وَإِنَّهَا لَكَبِيرَةٌ اِلَّا عَلَي اَ۬لْخَٰشِعِينَ (44) اَ۬لذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمْ وَأَنَّهُمُۥٓ إِلَيْهِ رَٰجِعُونَۖ (45) يَٰبَنِےٓ إِسْرَآءِيلَ اَ۟ذْكُرُواْ نِعْمَتِيَ اَ۬لتِےٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّے فَضَّلْتُكُمْ عَلَي اَ۬لْعَٰلَمِينَۖ (46) وَاتَّقُواْ يَوْماٗ لَّا تَجْزِے نَفْسٌ عَن نَّفْسٖ شَيْـٔاٗ وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةٞ وَلَا يُوخَذُ مِنْهَا عَدْلٞ وَلَا هُمْ يُنصَرُونَۖ (47) وَإِذْ نَجَّيْنَٰكُم مِّنَ اٰلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ اَ۬لْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْۖ وَفِے ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمْ عَظِيمٞۖ (48) وَإِذْ فَرَقْنَا بِكُمُ اُ۬لْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَۖ (49) وَإِذْ وَٰعَدْنَا مُوس۪يٰٓ أَرْبَعِينَ لَيْلَةٗ ثُمَّ اَ۪تَّخَذتُّمُ اُ۬لْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَۖ (50) ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَۖ (51) وَإِذَ اٰتَيْنَا مُوسَي اَ۬لْكِتَٰبَ وَالْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَۖ (52) ۞وَإِذْ قَالَ مُوس۪يٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمُۥٓ أَنفُسَكُم بِاتِّخَاذِكُمُ اُ۬لْعِجْلَ فَتُوبُوٓاْ إِلَيٰ بَارِئِكُمْ فَاقْتُلُوٓاْ أَنفُسَكُمْۖ ذَٰلِكُمْ خَيْرٞ لَّكُمْ عِندَ بَارِئِكُمْۖ فَتَابَ عَلَيْكُمُۥٓۖ إِنَّهُۥ هُوَ اَ۬لتَّوَّابُ اُ۬لرَّحِيمُۖ (53) وَإِذْ قُلْتُمْ يَٰمُوس۪يٰ لَن نُّومِنَ لَكَ حَتَّيٰ نَرَي اَ۬للَّهَ جَهْرَةٗ فَأَخَذَتْكُمُ اُ۬لصَّٰعِقَةُ وَأَنتُمْ تَنظُرُونَۖ (54) ثُمَّ بَعَثْنَٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَۖ (55) وَظَلَّلْنَا عَلَيْكُمُ اُ۬لْغَمَٰمَ وَأَنزَلْنَا عَلَيْكُمُ اُ۬لْمَنَّ وَالسَّلْو۪يٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْۖ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَۖ (56) وَإِذْ قُلْنَا اَ۟دْخُلُواْ هَٰذِهِ اِ۬لْقَرْيَةَ فَكُلُواْ مِنْهَا حَيْثُ شِئْتُمْ رَغَداٗ وَادْخُلُواْ اُ۬لْبَابَ سُجَّداٗ وَقُولُواْ حِطَّةٞ يُغْفَرْ لَكُمْ خَطَٰيٰ۪كُمْۖ وَسَنَزِيدُ اُ۬لْمُحْسِنِينَۖ (57) فَبَدَّلَ اَ۬لذِينَ ظَلَمُواْ قَوْلاً غَيْرَ اَ۬لذِے قِيلَ لَهُمْ فَأَنزَلْنَا عَلَي اَ۬لذِينَ ظَلَمُواْ رِجْزاٗ مِّنَ اَ۬لسَّمَآءِ بِمَا كَانُواْ يَفْسُقُونَۖ (58) ۞وَإِذِ اِ۪سْتَسْق۪يٰ مُوس۪يٰ لِقَوْمِهِۦ فَقُلْنَا اَ۪ضْرِب بِّعَصَاكَ اَ۬لْحَجَرَ فَانفَجَرَتْ مِنْهُ اُ۪ثْنَتَا عَشْرَةَ عَيْناٗۖ قَدْ عَلِمَ كُلُّ أُنَاسٖ مَّشْرَبَهُمْۖ كُلُواْ وَاشْرَبُواْ مِن رِّزْقِ اِ۬للَّهِۖ وَلَا تَعْثَوْاْ فِے اِ۬لَارْضِ مُفْسِدِينَۖ (59) وَإِذْ قُلْتُمْ يَٰمُوس۪يٰ لَن نَّصْبِرَ عَلَيٰ طَعَامٖ وَٰحِدٖ فَادْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ اُ۬لَارْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسْتَبْدِلُونَ اَ۬لذِے هُوَ أَدْن۪يٰ بِالذِے هُوَ خَيْرٌۖ اِ۪هْبِطُواْ مِصْراٗ فَإِنَّ لَكُم مَّا سَأَلْتُمْۖ وَضُرِبَتْ عَلَيْهِمُ اُ۬لذِّلَّةُ وَالْمَسْكَنَةُ وَبَآءُو بِغَضَبٖ مِّنَ اَ۬للَّهِۖ ذَٰلِكَ بِأَنَّهُمْ كَانُواْ يَكْفُرُونَ بِـَٔايَٰتِ اِ۬للَّهِ وَيَقْتُلُونَ اَ۬لنَّبِيٓـِٕۧنَ بِغَيْرِ اِ۬لْحَقِّۖ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعْتَدُونَۖ (60) إِنَّ اَ۬لذِينَ ءَامَنُواْ وَالذِينَ هَادُواْ وَالنَّصَٰر۪يٰ وَالصَّٰبِينَ مَنَ اٰمَنَ بِاللَّهِ وَالْيَوْمِ اِ۬لَاخِرِ وَعَمِلَ صَٰلِحاٗ فَلَهُمُۥٓ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۖ (61) وَإِذَ اَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ اُ۬لطُّورَۖ خُذُواْ مَآ ءَاتَيْنَٰكُم بِقُوَّةٖ وَاذْكُرُواْ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَۖ (62) ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَۖ فَلَوْلَا فَضْلُ اُ۬للَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ اَ۬لْخَٰسِرِينَۖ (63) وَلَقَدْ عَلِمْتُمُ اُ۬لذِينَ اَ۪عْتَدَوْاْ مِنكُمْ فِے اِ۬لسَّبْتِ فَقُلْنَا لَهُمْ كُونُواْ قِرَدَةً خَٰسِـِٕينَۖ (64) فَجَعَلْنَٰهَا نَكَٰلاٗ لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةٗ لِّلْمُتَّقِينَۖ (65) ۞وَإِذْ قَالَ مُوس۪يٰ لِقَوْمِهِۦٓ إِنَّ اَ۬للَّهَ يَامُرُكُمُۥٓ أَن تَذْبَحُواْ بَقَرَةٗۖ قَالُوٓاْ أَتَتَّخِذُنَا هُزُؤاٗۖ قَالَ أَعُوذُ بِاللَّهِ أَنَ اَكُونَ مِنَ اَ۬لْجَٰهِلِينَۖ (66) قَالُواْ اُ۟دْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۖ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا فَارِضٞ وَلَا بِكْرٌ عَوَانُۢ بَيْنَ ذَٰلِكَۖ فَافْعَلُواْ مَا تُومَرُونَۖ (67) قَالُواْ اُ۟دْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَاۖ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ صَفْرَآءُ فَاقِعٞ لَّوْنُهَاۖ تَسُرُّ اُ۬لنَّٰظِرِينَۖ (68) قَالُواْ اُ۟دْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ اَ۬لْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ اَ۬للَّهُ لَمُهْتَدُونَۖ (69) قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا ذَلُولٞ تُثِيرُ اُ۬لَارْضَ وَلَا تَسْقِے اِ۬لْحَرْثَۖ مُسَلَّمَةٞ لَّا شِيَةَ فِيهَاۖ قَالُواْ اُ۬لَٰنَ جِئْتَ بِالْحَقِّۖ فَذَبَحُوهَا وَمَا كَادُواْ يَفْعَلُونَۖ (70) وَإِذْ قَتَلْتُمْ نَفْساٗ فَادَّٰرَٰٔتُمْ فِيهَاۖ وَاللَّهُ مُخْرِجٞ مَّا كُنتُمْ تَكْتُمُونَۖ (71) فَقُلْنَا اَ۪ضْرِبُوهُ بِبَعْضِهَاۖ كَذَٰلِكَ يُحْيِ اِ۬للَّهُ اُ۬لْمَوْت۪يٰ وَيُرِيكُمُۥٓ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَۖ (72) ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِيَ كَالْحِجَارَةِ أَوَ اَشَدُّ قَسْوَةٗۖ وَإِنَّ مِنَ اَ۬لْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ اُ۬لَانْهَٰرُۖ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ اُ۬لْمَآءُۖ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ اِ۬للَّهِۖ وَمَا اَ۬للَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَۖ (73) أَفَتَطْمَعُونَ أَنْ يُّومِنُواْ لَكُمْ وَقَدْ كَانَ فَرِيقٞ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ اَ۬للَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَۖ (74) ۞وَإِذَا لَقُواْ اُ۬لذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّاۖ وَإِذَا خَلَا بَعْضُهُمُۥٓ إِلَيٰ بَعْضٖ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ اَ۬للَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمُۥٓۖ أَفَلَا تَعْقِلُونَۖ (75) أَوَلَا يَعْلَمُونَ أَنَّ اَ۬للَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَۖ (76) وَمِنْهُمُۥٓ أُمِّيُّونَ لَا يَعْلَمُونَ اَ۬لْكِتَٰبَ إِلَّآ أَمَانِيَّۖ وَإِنْ هُمُۥٓ إِلَّا يَظُنُّونَۖ (77) فَوَيْلٞ لِّلذِينَ يَكْتُبُونَ اَ۬لْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ اِ۬للَّهِ لِيَشْتَرُواْ بِهِۦ ثَمَناٗ قَلِيلاٗۖ فَوَيْلٞ لَّهُم مِّمَّا كَتَبَتَ اَيْدِيهِمْ وَوَيْلٞ لَّهُم مِّمَّا يَكْسِبُونَۖ (78) وَقَالُواْ لَن تَمَسَّنَا اَ۬لنَّارُ إِلَّآ أَيَّاماٗ مَّعْدُودَةٗۖ قُلَ اَتَّخَذتُّمْ عِندَ اَ۬للَّهِ عَهْداٗ فَلَنْ يُّخْلِفَ اَ۬للَّهُ عَهْدَهُۥٓۖ أَمْ تَقُولُونَ عَلَي اَ۬للَّهِ مَا لَا تَعْلَمُونَۖ (79) بَل۪يٰ مَن كَسَبَ سَيِّئَةٗ وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٰٔتُهُۥ فَأُوْلَٰٓئِكَ أَصْحَٰبُ اُ۬لنّ۪ارِ هُمْ فِيهَا خَٰلِدُونَۖ (80) وَالذِينَ ءَامَنُواْ وَعَمِلُواْ اُ۬لصَّٰلِحَٰتِ أُوْلَٰٓئِكَ أَصْحَٰبُ اُ۬لْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَۖ (81) وَإِذَ اَخَذْنَا مِيثَٰقَ بَنِےٓ إِسْرَآءِيلَ لَا تَعْبُدُونَ إِلَّا اَ۬للَّهَۖ وَبِالْوَٰلِدَيْنِ إِحْسَٰناٗ وَذِے اِ۬لْقُرْب۪يٰ وَالْيَتَٰم۪يٰ وَالْمَسَٰكِينِۖ وَقُولُواْ لِلنَّاسِ حُسْناٗۖ وَأَقِيمُواْ اُ۬لصَّلَوٰةَ وَءَاتُواْ اُ۬لزَّكَوٰةَۖ ثُمَّ تَوَلَّيْتُمُۥٓ إِلَّا قَلِيلاٗ مِّنكُمْ وَأَنتُم مُّعْرِضُونَۖ (82) وَإِذَ اَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيٰ۪رِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَۖ (83) ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقاٗ مِّنكُم مِّن دِيٰ۪رِهِمْ تَظَّٰهَرُونَ عَلَيْهِم بِالِاثْمِ وَالْعُدْوَٰنِۖ ۞وَإِنْ يَّاتُوكُمُۥٓ أُسَٰر۪يٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمُۥٓ إِخْرَاجُهُمُۥٓۖ أَفَتُومِنُونَ بِبَعْضِ اِ۬لْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٖۖ فَمَا جَزَآءُ مَنْ يَّفْعَلُ ذَٰلِكَ مِنكُمُۥٓ إِلَّا خِزْيٞ فِے اِ۬لْحَيَوٰةِ اِ۬لدُّنْي۪اۖ وَيَوْمَ اَ۬لْقِيَٰمَةِ يُرَدُّونَ إِلَيٰٓ أَشَدِّ اِ۬لْعَذَابِۖ وَمَا اَ۬للَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَۖ (84) أُوْلَٰٓئِكَ اَ۬لذِينَ اَ۪شْتَرَوُاْ اُ۬لْحَيَوٰةَ اَ۬لدُّنْي۪ا بِالَاخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ اُ۬لْعَذَابُ وَلَا هُمْ يُنصَرُونَۖ (85) وَلَقَدَ اٰتَيْنَا مُوسَي اَ۬لْكِتَٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِالرُّسُلِۖ وَءَاتَيْنَا عِيسَي اَ۪بْنَ مَرْيَمَ اَ۬لْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ اِ۬لْقُدُسِۖ أَفَكُلَّمَا جَآءَكُمْ رَسُولُۢ بِمَا لَا تَهْو۪يٰٓ أَنفُسُكُمُ اُ۪سْتَكْبَرْتُمْۖ فَفَرِيقاٗ كَذَّبْتُمْ وَفَرِيقاٗ تَقْتُلُونَۖ (86) وَقَالُواْ قُلُوبُنَا غُلْفُۢۖ بَل لَّعَنَهُمُ اُ۬للَّهُ بِكُفْرِهِمْ فَقَلِيلاٗ مَّا يُومِنُونَۖ (87) وَلَمَّا جَآءَهُمْ كِتَٰبٞ مِّنْ عِندِ اِ۬للَّهِ مُصَدِّقٞ لِّمَا مَعَهُمْ وَكَانُواْ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَي اَ۬لذِينَ كَفَرُواْ فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۖ فَلَعْنَةُ اُ۬للَّهِ عَلَي اَ۬لْكٰ۪فِرِينَۖ (88) بِيسَمَا اَ۪شْتَرَوْاْ بِهِۦٓ أَنفُسَهُمُۥٓ أَنْ يَّكْفُرُواْ بِمَآ أَنزَلَ اَ۬للَّهُ بَغْياً اَنْ يُّنَزِّلَ اَ۬للَّهُ مِن فَضْلِهِۦ عَلَيٰ مَنْ يَّشَآءُ مِنْ عِبَادِهِۦۖ فَبَآءُو بِغَضَبٍ عَلَيٰ غَضَبٖۖ وَلِلْكٰ۪فِرِينَ عَذَابٞ مُّهِينٞۖ (89) وَإِذَا قِيلَ لَهُمُۥٓ ءَامِنُواْ بِمَآ أَنزَلَ اَ۬للَّهُ قَالُواْ نُومِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ اَ۬لْحَقُّ مُصَدِّقاٗ لِّمَا مَعَهُمْۖ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِئَآءَ اَ۬للَّهِ مِن قَبْلُ إِن كُنتُم مُّومِنِينَۖ (90) ۞وَلَقَدْ جَآءَكُم مُّوس۪يٰ بِالْبَيِّنَٰتِ ثُمَّ اَ۪تَّخَذتُّمُ اُ۬لْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَۖ (91) وَإِذَ اَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ اُ۬لطُّورَۖ خُذُواْ مَآ ءَاتَيْنَٰكُم بِقُوَّةٖ وَاسْمَعُواْۖ قَالُواْ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُواْ فِے قُلُوبِهِمُ اُ۬لْعِجْلَ بِكُفْرِهِمْۖ قُلْ بِيسَمَا يَامُرُكُم بِهِۦٓ إِيمَٰنُكُمُۥٓ إِن كُنتُم مُّومِنِينَۖ (92) قُلِ اِن كَانَتْ لَكُمُ اُ۬لدَّارُ اُ۬لَاخِرَةُ عِندَ اَ۬للَّهِ خَالِصَةٗ مِّن دُونِ اِ۬لنَّاسِ فَتَمَنَّوُاْ اُ۬لْمَوْتَ إِن كُنتُمْ صَٰدِقِينَۖ (93) وَلَنْ يَّتَمَنَّوْهُ أَبَداَۢ بِمَا قَدَّمَتَ اَيْدِيهِمْۖ وَاللَّهُ عَلِيمُۢ بِالظَّٰلِمِينَۖ (94) وَلَتَجِدَنَّهُمُۥٓ أَحْرَصَ اَ۬لنَّاسِ عَلَيٰ حَيَوٰةٖۖ وَمِنَ اَ۬لذِينَ أَشْرَكُواْ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٖۖ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ اَ۬لْعَذَابِ أَنْ يُّعَمَّرَۖ وَاللَّهُ بَصِيرُۢ بِمَا يَعْمَلُونَۖ (95) قُلْ مَن كَانَ عَدُوّاٗ لِّـجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَيٰ قَلْبِكَ بِإِذْنِ اِ۬للَّهِ مُصَدِّقاٗ لِّمَا بَيْنَ يَدَيْهِ وَهُديٗ وَبُشْر۪يٰ لِلْمُومِنِينَۖ (96) مَن كَانَ عَدُوّاٗ لِّلهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَٰٓئِلَ فَإِنَّ اَ۬للَّهَ عَدُوّٞ لِّلْكٰ۪فِرِينَۖ (97) وَلَقَدَ اَنزَلْنَآ إِلَيْكَ ءَايَٰتِۢ بَيِّنَٰتٖۖ وَمَا يَكْفُرُ بِهَآ إِلَّا اَ۬لْفَٰسِقُونَۖ (98) أَوَكُلَّمَا عَٰهَدُواْ عَهْداٗ نَّبَذَهُۥ فَرِيقٞ مِّنْهُمۖ بَلَ اَكْثَرُهُمْ لَا يُومِنُونَۖ (99) ۞وَلَمَّا جَآءَهُمْ رَسُولٞ مِّنْ عِندِ اِ۬للَّهِ مُصَدِّقٞ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٞ مِّنَ اَ۬لذِينَ أُوتُواْ اُ۬لْكِتَٰبَ كِتَٰبَ اَ۬للَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَۖ (100) وَاتَّبَعُواْ مَا تَتْلُواْ اُ۬لشَّيَٰطِينُ عَلَيٰ مُلْكِ سُلَيْمَٰنَۖ وَمَا كَفَرَ سُلَيْمَٰنُ وَلَٰكِنَّ اَ۬لشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ اَ۬لنَّاسَ اَ۬لسِّحْرَ وَمَآ أُنزِلَ عَلَي اَ۬لْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَۖ وَمَا يُعَلِّمَٰنِ مِنَ اَحَدٍ حَتَّيٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٞ فَلَا تَكْفُرْۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ اَ۬لْمَرْءِ وَزَوْجِهِۦۖ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنَ اَحَدٍ اِلَّا بِإِذْنِ اِ۬للَّهِۖ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْۖ وَلَقَدْ عَلِمُواْ لَمَنِ اِ۪شْتَر۪يٰهُ مَا لَهُۥ فِے اِ۬لَاخِرَةِ مِنْ خَلَٰقٖۖ وَلَبِيسَ مَا شَرَوْاْ بِهِۦٓ أَنفُسَهُمْ لَوْ كَانُواْ يَعْلَمُونَۖ (101) وَلَوَ اَنَّهُمُۥٓ ءَامَنُواْ وَاتَّقَوْاْ لَمَثُوبَةٞ مِّنْ عِندِ اِ۬للَّهِ خَيْرٞ لَّوْ كَانُواْ يَعْلَمُونَۖ (102) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ اُ۟نظُرْنَا وَاسْمَعُواْۖ وَلِلْكٰ۪فِرِينَ عَذَابٌ اَلِيمٞۖ (103) مَّا يَوَدُّ اُ۬لذِينَ كَفَرُواْ مِنَ اَهْلِ اِ۬لْكِتَٰبِ وَلَا اَ۬لْمُشْرِكِينَ أَنْ يُّنَزَّلَ عَلَيْكُم مِّنْ خَيْرٖ مِّن رَّبِّكُمْۖ وَاللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَنْ يَّشَآءُۖ وَاللَّهُ ذُو اُ۬لْفَضْلِ اِ۬لْعَظِيمِۖ (104) ۞مَا نَنسَخْ مِنَ اٰيَةٍ اَوْ نُنسِهَا نَاتِ بِخَيْرٖ مِّنْهَآ أَوْ مِثْلِهَآۖ أَلَمْ تَعْلَمَ اَنَّ اَ۬للَّهَ عَلَيٰ كُلِّ شَےْءٖ قَدِيرٌۖ (105) اَلَمْ تَعْلَمَ اَنَّ اَ۬للَّهَ لَهُۥ مُلْكُ اُ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا لَكُم مِّن دُونِ اِ۬للَّهِ مِنْ وَّلِيّٖ وَلَا نَصِيرٍۖ (106) اَمْ تُرِيدُونَ أَن تَسْـَٔلُواْ رَسُولَكُمْ كَمَا سُئِلَ مُوس۪يٰ مِن قَبْلُۖ وَمَنْ يَّتَبَدَّلِ اِ۬لْكُفْرَ بِالِايمَٰنِ فَقَد ضَّلَّ سَوَآءَ اَ۬لسَّبِيلِۖ (107) وَدَّ كَثِيرٞ مِّنَ اَهْلِ اِ۬لْكِتَٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَٰنِكُمْ كُفَّاراًۖ حَسَداٗ مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ اُ۬لْحَقُّۖ فَاعْفُواْ وَاصْفَحُواْ حَتَّيٰ يَاتِيَ اَ۬للَّهُ بِأَمْرِهِۦٓۖ إِنَّ اَ۬للَّهَ عَلَيٰ كُلِّ شَےْءٖ قَدِيرٞۖ (108) وَأَقِيمُواْ اُ۬لصَّلَوٰةَ وَءَاتُواْ اُ۬لزَّكَوٰةَۖ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرٖ تَجِدُوهُ عِندَ اَ۬للَّهِۖ إِنَّ اَ۬للَّهَ بِمَا تَعْمَلُونَ بَصِيرٞۖ (109) وَقَالُواْ لَنْ يَّدْخُلَ اَ۬لْجَنَّةَ إِلَّا مَن كَانَ هُوداً اَوْ نَصَٰر۪يٰۖ تِلْكَ أَمَانِيُّهُمْۖ قُلْ هَاتُواْ بُرْهَٰنَكُمُۥٓ إِن كُنتُمْ صَٰدِقِينَۖ (110) بَل۪يٰ مَنَ اَسْلَمَ وَجْهَهُۥ لِلهِ وَهُوَ مُحْسِنٞ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۖ (111) وَقَالَتِ اِ۬لْيَهُودُ لَيْسَتِ اِ۬لنَّصَٰر۪يٰ عَلَيٰ شَےْءٖ وَقَالَتِ اِ۬لنَّصَٰر۪يٰ لَيْسَتِ اِ۬لْيَهُودُ عَلَيٰ شَےْءٖ وَهُمْ يَتْلُونَ اَ۬لْكِتَٰبَۖ كَذَٰلِكَ قَالَ اَ۬لذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْۖ فَاللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ اَ۬لْقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخْتَلِفُونَۖ (112) ۞وَمَنَ اَظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ اَ۬للَّهِ أَنْ يُّذْكَرَ فِيهَا اَ۪سْمُهُۥ وَسَع۪يٰ فِے خَرَابِهَآۖ أُوْلَٰٓئِكَ مَا كَانَ لَهُمُۥٓ أَنْ يَّدْخُلُوهَآ إِلَّا خَآئِفِينَۖ لَهُمْ فِے اِ۬لدُّنْي۪ا خِزْيٞ وَلَهُمْ فِے اِ۬لَاخِرَةِ عَذَابٌ عَظِيمٞۖ (113) وَلِلهِ اِ۬لْمَشْرِقُ وَالْمَغْرِبُۖ فَأَيْنَمَا تُوَلُّواْ فَثَمَّ وَجْهُ اُ۬للَّهِۖ إِنَّ اَ۬للَّهَ وَٰسِعٌ عَلِيمٞۖ (114) وَقَالُواْ اُ۪تَّخَذَ اَ۬للَّهُ وَلَداٗۖ سُبْحَٰنَهُۥۖ بَل لَّهُۥ مَا فِے اِ۬لسَّمَٰوَٰتِ وَالَارْضِۖ كُلّٞ لَّهُۥ قَٰنِتُونَۖ (115) بَدِيعُ اُ۬لسَّمَٰوَٰتِ وَالَارْضِۖ وَإِذَا قَض۪يٰٓ أَمْراٗ فَإِنَّمَا يَقُولُ لَهُۥ كُنۖ فَيَكُونُۖ (116) وَقَالَ اَ۬لذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا اَ۬للَّهُ أَوْ تَاتِينَآ ءَايَةٞۖ كَذَٰلِكَ قَالَ اَ۬لذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْۖ تَشَٰبَهَتْ قُلُوبُهُمْۖ قَدْ بَيَّنَّا اَ۬لَايَٰتِ لِقَوْمٖ يُوقِنُونَۖ (117) إِنَّآ أَرْسَلْنَٰكَ بِالْحَقِّ بَشِيراٗ وَنَذِيراٗۖ وَلَا تَسْـَٔلْ عَنَ اَصْحَٰبِ اِ۬لْجَحِيمِۖ (118) وَلَن تَرْض۪يٰ عَنكَ اَ۬لْيَهُودُ وَلَا اَ۬لنَّصَٰر۪يٰ حَتَّيٰ تَتَّبِعَ مِلَّتَهُمْۖ قُلِ اِنَّ هُدَي اَ۬للَّهِ هُوَ اَ۬لْهُد۪يٰۖ وَلَئِنِ اِ۪تَّبَعْتَ أَهْوَآءَهُم بَعْدَ اَ۬لذِے جَآءَكَ مِنَ اَ۬لْعِلْمِ مَا لَكَ مِنَ اَ۬للَّهِ مِنْ وَّلِيّٖ وَلَا نَصِيرٍۖ (119) اِ۬لذِينَ ءَاتَيْنَٰهُمُ اُ۬لْكِتَٰبَ يَتْلُونَهُۥ حَقَّ تِلَٰوَتِهِۦٓ أُوْلَٰٓئِكَ يُومِنُونَ بِهِۦۖ وَمَنْ يَّكْفُرْ بِهِۦ فَأُوْلَٰٓئِكَ هُمُ اُ۬لْخَٰسِرُونَۖ (120) يَٰبَنِےٓ إِسْرَآءِيلَ اَ۟ذْكُرُواْ نِعْمَتِيَ اَ۬لتِےٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّے فَضَّلْتُكُمْ عَلَي اَ۬لْعَٰلَمِينَۖ (121) وَاتَّقُواْ يَوْماٗ لَّا تَجْزِے نَفْسٌ عَن نَّفْسٖ شَيْـٔاٗ وَلَا يُقْبَلُ مِنْهَا عَدْلٞ وَلَا تَنفَعُهَا شَفَٰعَةٞ وَلَا هُمْ يُنصَرُونَۖ (122) ۞وَإِذِ اِ۪بْتَل۪يٰٓ إِبْرَٰهِـيمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ قَالَ إِنِّے جَاعِلُكَ لِلنَّاسِ إِمَاماٗۖ قَالَ وَمِن ذُرِّيَّتِےۖ قَالَ لَا يَنَالُ عَهْدِيَ اَ۬لظَّٰلِمِينَۖ (123) وَإِذْ جَعَلْنَا اَ۬لْبَيْتَ مَثَابَةٗ لِّلنَّاسِ وَأَمْناٗ وَاتَّخَذُواْ مِن مَّقَامِ إِبْرَٰهِيمَ مُصَلّيٗۖ وَعَهِدْنَآ إِلَيٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ أَن طَهِّرَا بَيْتِيَ لِلطَّآئِفِينَ وَالْعَٰكِفِينَ وَالرُّكَّعِ اِ۬لسُّجُودِۖ (124) وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ اِ۪جْعَلْ هَٰذَا بَلَداً اٰمِناٗ وَارْزُقَ اَهْلَهُۥ مِنَ اَ۬لثَّمَرَٰتِ مَنَ اٰمَنَ مِنْهُم بِاللَّهِ وَالْيَوْمِ اِ۬لَاخِرِۖ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلاٗ ثُمَّ أَضْطَرُّهُۥٓ إِلَيٰ عَذَابِ اِ۬لنّ۪ارِۖ وَبِيسَ اَ۬لْمَصِيرُۖ (125) وَإِذْ يَرْفَعُ إِبْرَٰهِيمُ اُ۬لْقَوَاعِدَ مِنَ اَ۬لْبَيْتِ وَإِسْمَٰعِيلُۖ رَبَّنَا تَقَبَّلْ مِنَّآ إِنَّكَ أَنتَ اَ۬لسَّمِيعُ اُ۬لْعَلِيمُۖ (126) رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسْلِمَةٗ لَّكَۖ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآۖ إِنَّكَ أَنتَ اَ۬لتَّوَّابُ اُ۬لرَّحِيمُۖ (127) رَبَّنَا وَابْعَثْ فِيهِمْ رَسُولاٗ مِّنْهُمْ يَتْلُواْ عَلَيْهِمُۥٓ ءَايَٰتِكَ وَيُعَلِّمُهُمُ اُ۬لْكِتَٰبَ وَالْحِكْمَةَ وَيُزَكِّيهِمُۥٓۖ إِنَّكَ أَنتَ اَ۬لْعَزِيزُ اُ۬لْحَكِيمُۖ (128) وَمَنْ يَّرْغَبُ عَن مِّلَّةِ إِبْرَٰهِيمَ إِلَّا مَن سَفِهَ نَفْسَهُۥۖ وَلَقَدِ اِ۪صْطَفَيْنَٰهُ فِے اِ۬لدُّنْي۪اۖ وَإِنَّهُۥ فِے اِ۬لَاخِرَةِ لَمِنَ اَ۬لصَّٰلِحِينَۖ (129) إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْۖ قَالَ أَسْلَمْتُ لِرَبِّ اِ۬لْعَٰلَمِينَۖ (130) وَأَوْص۪يٰ بِهَآ إِبْرَٰهِيمُ بَنِيهِۖ وَيَعْقُوبُ يَٰبَنِيَّ إِنَّ اَ۬للَّهَ اَ۪صْطَف۪يٰ لَكُمُ اُ۬لدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَۖ (131) ۞أَمْ كُنتُمْ شُهَدَآءَ ا۪ذْ حَضَرَ يَعْقُوبَ اَ۬لْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِےۖ قَالُواْ نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ إِلَٰهاٗ وَٰحِداٗ وَنَحْنُ لَهُۥ مُسْلِمُونَۖ (132) تِلْكَ أُمَّةٞ قَدْ خَلَتْۖ لَهَا مَا كَسَبَتْۖ وَلَكُم مَّا كَسَبْتُمْۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُواْ يَعْمَلُونَۖ (133) وَقَالُواْ كُونُواْ هُوداً اَوْ نَصَٰر۪يٰ تَهْتَدُواْۖ قُلْ بَلْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفاٗۖ وَمَا كَانَ مِنَ اَ۬لْمُشْرِكِينَۖ (134) قُولُوٓاْ ءَامَنَّا بِاللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَيٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَالَاسْبَاطِ وَمَآ أُوتِيَ مُوس۪يٰ وَعِيس۪يٰ وَمَآ أُوتِيَ اَ۬لنَّبِيٓـُٔونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٖ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَۖ (135) فَإِنَ اٰمَنُواْ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ اِ۪هْتَدَواْۖ وَّإِن تَوَلَّوْاْ فَإِنَّمَا هُمْ فِے شِقَاقٖۖ فَسَيَكْفِيكَهُمُ اُ۬للَّهُۖ وَهُوَ اَ۬لسَّمِيعُ اُ۬لْعَلِيمُۖ (136) صِبْغَةَ اَ۬للَّهِۖ وَمَنَ اَحْسَنُ مِنَ اَ۬للَّهِ صِبْغَةٗۖ وَنَحْنُ لَهُۥ عَٰبِدُونَۖ (137) قُلَ اَتُحَآجُّونَنَا فِے اِ۬للَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَٰلُنَا وَلَكُمُۥٓ أَعْمَٰلُكُمْۖ وَنَحْنُ لَهُۥ مُخْلِصُونَۖ (138) أَمْ يَقُولُونَ إِنَّ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَالَاسْبَاطَ كَانُواْ هُوداً اَوْ نَصَٰر۪يٰۖ قُلَ آٰنتُمُۥٓ أَعْلَمُ أَمِ اِ۬للَّهُۖ وَمَنَ اَظْلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ اَ۬للَّهِۖ وَمَا اَ۬للَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَۖ (139) تِلْكَ أُمَّةٞ قَدْ خَلَتْۖ لَهَا مَا كَسَبَتْۖ وَلَكُم مَّا كَسَبْتُمْۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُواْ يَعْمَلُونَۖ (140) ۞سَيَقُولُ اُ۬لسُّفَهَآءُ مِنَ اَ۬لنَّاسِ مَا وَلّ۪يٰهُمْ عَن قِبْلَتِهِمُ اُ۬لتِے كَانُواْ عَلَيْهَاۖ قُل لِّلهِ اِ۬لْمَشْرِقُ وَالْمَغْرِبُۖ يَهْدِے مَنْ يَّشَآءُ اِ۪لَيٰ صِرَٰطٖ مُّسْتَقِيمٖۖ (141) وَكَذَٰلِكَ جَعَلْنَٰكُمُۥٓ أُمَّةٗ وَسَطاٗ لِّتَكُونُواْ شُهَدَآءَ عَلَي اَ۬لنَّاسِ وَيَكُونَ اَ۬لرَّسُولُ عَلَيْكُمْ شَهِيداٗۖ وَمَا جَعَلْنَا اَ۬لْقِبْلَةَ اَ۬لتِے كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَنْ يَّتَّبِعُ اُ۬لرَّسُولَ مِمَّنْ يَّنقَلِبُ عَلَيٰ عَقِبَيْهِۖ وَإِن كَانَتْ لَكَبِيرَةً اِلَّا عَلَي اَ۬لذِينَ هَدَي اَ۬للَّهُۖ وَمَا كَانَ اَ۬للَّهُ لِيُضِيعَ إِيمَٰنَكُمُۥٓۖ إِنَّ اَ۬للَّهَ بِالنَّاسِ لَرَءُوفٞ رَّحِيمٞۖ (142) قَدْ نَر۪يٰ تَقَلُّبَ وَجْهِكَ فِے اِ۬لسَّمَآءِ فَلَنُوَلِّيَنَّكَ قِبْلَةٗ تَرْض۪يٰهَاۖ فَوَلِّ وَجْهَكَ شَطْرَ اَ۬لْمَسْجِدِ اِ۬لْحَرَامِۖ وَحَيْثُ مَا كُنتُمْ فَوَلُّواْ وُجُوهَكُمْ شَطْرَهُۥۖ وَإِنَّ اَ۬لذِينَ أُوتُواْ اُ۬لْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ اُ۬لْحَقُّ مِن رَّبِّهِمْۖ وَمَا اَ۬للَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَۖ (143) وَلَئِنَ اَتَيْتَ اَ۬لذِينَ أُوتُواْ اُ۬لْكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبْلَتَكَۖ وَمَآ أَنتَ بِتَابِعٖ قِبْلَتَهُمْۖ وَمَا بَعْضُهُم بِتَابِعٖ قِبْلَةَ بَعْضٖۖ وَلَئِنِ اِ۪تَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ اَ۬لْعِلْمِ إِنَّكَ إِذاٗ لَّمِنَ اَ۬لظَّٰلِمِينَۖ (144) اَ۬لذِينَ ءَاتَيْنَٰهُمُ اُ۬لْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْۖ وَإِنَّ فَرِيقاٗ مِّنْهُمْ لَيَكْتُمُونَ اَ۬لْحَقَّ وَهُمْ يَعْلَمُونَۖ (145) اَ۬لْحَقُّ مِن رَّبِّكَۖ فَلَا تَكُونَنَّ مِنَ اَ۬لْمُمْتَرِينَۖ (146) ۞وَلِكُلّٖ وِجْهَةٌ هُوَ مُوَلِّيهَا فَاسْتَبِقُواْ اُ۬لْخَيْرَٰتِۖ أَيْنَ مَا تَكُونُواْ يَاتِ بِكُمُ اُ۬للَّهُ جَمِيعاًۖ اِنَّ اَ۬للَّهَ عَلَيٰ كُلِّ شَےْءٖ قَدِيرٞۖ (147) وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ اَ۬لْمَسْجِدِ اِ۬لْحَرَامِۖ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَۖ وَمَا اَ۬للَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَۖ (148) وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ اَ۬لْمَسْجِدِ اِ۬لْحَرَامِۖ وَحَيْثُ مَا كُنتُمْ فَوَلُّواْ وُجُوهَكُمْ شَطْرَهُۥ لِيَ۬لَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ اِلَّا اَ۬لذِينَ ظَلَمُواْ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِےۖ وَلِأُتِمَّ نِعْمَتِے عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَۖ (149) كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولاٗ مِّنكُمْ يَتْلُواْ عَلَيْكُمُۥٓ ءَايَٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ اُ۬لْكِتَٰبَ وَالْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُواْ تَعْلَمُونَ (150) فَاذْكُرُونِےٓ أَذْكُرْكُمْ وَاشْكُرُواْ لِے وَلَا تَكْفُرُونِۖ (151) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ اُ۪سْتَعِينُواْ بِالصَّبْرِ وَالصَّلَوٰةِۖ إِنَّ اَ۬للَّهَ مَعَ اَ۬لصَّٰبِرِينَۖ (152) وَلَا تَقُولُواْ لِمَنْ يُّقْتَلُ فِے سَبِيلِ اِ۬للَّهِ أَمْوَٰتُۢۖ بَلَ اَحْيَآءٞ وَلَٰكِن لَّا تَشْعُرُونَۖ (153) وَلَنَبْلُوَنَّكُم بِشَےْءٖ مِّنَ اَ۬لْخَوْفِ وَالْجُوعِ وَنَقْصٖ مِّنَ اَ۬لَامْوَٰلِ وَالَانفُسِ وَالثَّمَرَٰتِۖ وَبَشِّرِ اِ۬لصَّٰبِرِينَ (154) اَ۬لذِينَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَۖ (155) أُوْلَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٞ مِّن رَّبِّهِمْ وَرَحْمَةٞۖ وَأُوْلَٰٓئِكَ هُمُ اُ۬لْمُهْتَدُونَۖ (156) ۞إِنَّ اَ۬لصَّفَا وَالْمَرْوَةَ مِن شَعَٰٓئِرِ اِ۬للَّهِۖ فَمَنْ حَجَّ اَ۬لْبَيْتَ أَوِ اِ۪عْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَّطَّوَّفَ بِهِمَاۖ وَمَن تَطَوَّعَ خَيْراٗ فَإِنَّ اَ۬للَّهَ شَاكِرٌ عَلِيمٌۖ (157) اِنَّ اَ۬لذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ اَ۬لْبَيِّنَٰتِ وَالْهُد۪يٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِے اِ۬لْكِتَٰبِ أُوْلَٰٓئِكَ يَلْعَنُهُمُ اُ۬للَّهُ وَيَلْعَنُهُمُ اُ۬للَّٰعِنُونَ (158) إِلَّا اَ۬لذِينَ تَابُواْ وَأَصْلَحُواْ وَبَيَّنُواْ فَأُوْلَٰٓئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا اَ۬لتَّوَّابُ اُ۬لرَّحِيمُۖ (159) إِنَّ اَ۬لذِينَ كَفَرُواْ وَمَاتُواْ وَهُمْ كُفَّارٌ ا۟وْلَٰٓئِكَ عَلَيْهِمْ لَعْنَةُ اُ۬للَّهِ وَالْمَلَٰٓئِكَةِ وَالنَّاسِ أَجْمَعِينَ (160) خَٰلِدِينَ فِيهَاۖ لَا يُخَفَّفُ عَنْهُمُ اُ۬لْعَذَابُ وَلَا هُمْ يُنظَرُونَۖ (161) وَإِلَٰهُكُمُۥٓ إِلَٰهٞ وَٰحِدٞۖ لَّآ إِلَٰهَ إِلَّا هُوَ اَ۬لرَّحْمَٰنُ اُ۬لرَّحِيمُۖ (162) إِنَّ فِے خَلْقِ اِ۬لسَّمَٰوَٰتِ وَالَارْضِ وَاخْتِلَٰفِ اِ۬ليْلِ وَالنَّه۪ارِ وَالْفُلْكِ اِ۬لتِے تَجْرِے فِے اِ۬لْبَحْرِ بِمَا يَنفَعُ اُ۬لنَّاسَ وَمَآ أَنزَلَ اَ۬للَّهُ مِنَ اَ۬لسَّمَآءِ مِن مَّآءٖ فَأَحْي۪ا بِهِ اِ۬لَارْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖ وَتَصْرِيفِ اِ۬لرِّيَٰحِ وَالسَّحَابِ اِ۬لْمُسَخَّرِ بَيْنَ اَ۬لسَّمَآءِ وَالَارْضِ لَأٓيَٰتٖ لِّقَوْمٖ يَعْقِلُونَۖ (163) وَمِنَ اَ۬لنَّاسِ مَنْ يَّتَّخِذُ مِن دُونِ اِ۬للَّهِ أَندَاداٗ يُحِبُّونَهُمْ كَحُبِّ اِ۬للَّهِۖ وَالذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّاٗ لِّلهِۖ وَلَوْ تَرَي اَ۬لذِينَ ظَلَمُوٓاْ إِذْ يَرَوْنَ اَ۬لْعَذَابَ أَنَّ اَ۬لْقُوَّةَ لِلهِ جَمِيعاٗ وَأَنَّ اَ۬للَّهَ شَدِيدُ اُ۬لْعَذَابِۖ (164) ۞إِذْ تَبَرَّأَ اَ۬لذِينَ اَ۟تُّبِعُواْ مِنَ اَ۬لذِينَ اَ۪تَّبَعُواْ وَرَأَوُاْ اُ۬لْعَذَابَ وَتَقَطَّعَتْ بِهِمُ اُ۬لَاسْبَٰبُۖ (165) وَقَالَ اَ۬لذِينَ اَ۪تَّبَعُواْ لَوَ اَنَّ لَنَا كَرَّةٗ فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُواْ مِنَّاۖ كَذَٰلِكَ يُرِيهِمُ اُ۬للَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْۖ وَمَا هُم بِخَٰرِجِينَ مِنَ اَ۬لنّ۪ارِۖ (166) يَٰٓأَيُّهَا اَ۬لنَّاسُ كُلُواْ مِمَّا فِے اِ۬لَارْضِ حَلَٰلاٗ طَيِّباٗ وَلَا تَتَّبِعُواْ خُطْوَٰتِ اِ۬لشَّيْطَٰنِۖ إِنَّهُۥ لَكُمْ عَدُوّٞ مُّبِينٌۖ (167) اِنَّمَا يَامُرُكُم بِالسُّوٓءِ وَالْفَحْشَآءِ وَأَن تَقُولُواْ عَلَي اَ۬للَّهِ مَا لَا تَعْلَمُونَۖ (168) وَإِذَا قِيلَ لَهُمُ اُ۪تَّبِعُواْ مَآ أَنزَلَ اَ۬للَّهُ قَالُواْ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآۖ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـٔاٗ وَلَا يَهْتَدُونَۖ (169) وَمَثَلُ اُ۬لذِينَ كَفَرُواْ كَمَثَلِ اِ۬لذِے يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۖ صُمُّۢ بُكْمٌ عُمْيٞ فَهُمْ لَا يَعْقِلُونَۖ (170) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَاشْكُرُواْ لِلهِ إِن كُنتُمُۥٓ إِيَّاهُ تَعْبُدُونَۖ (171) إِنَّمَا حَرَّمَ عَلَيْكُمُ اُ۬لْمَيْتَةَ وَالدَّمَ وَلَحْمَ اَ۬لْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ اِ۬للَّهِۖ فَمَنُ اُ۟ضْطُرَّ غَيْرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثْمَ عَلَيْهِۖ إِنَّ اَ۬للَّهَ غَفُورٞ رَّحِيمٌۖ (172) اِنَّ اَ۬لذِينَ يَكْتُمُونَ مَآ أَنزَلَ اَ۬للَّهُ مِنَ اَ۬لْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَناٗ قَلِيلاً ا۟وْلَٰٓئِكَ مَا يَاكُلُونَ فِے بُطُونِهِمُۥٓ إِلَّا اَ۬لنَّارَ وَلَا يُكَلِّمُهُمُ اُ۬للَّهُ يَوْمَ اَ۬لْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ اَلِيمٌۖ (173) ا۟وْلَٰٓئِكَ اَ۬لذِينَ اَ۪شْتَرَوُاْ اُ۬لضَّلَٰلَةَ بِالْهُد۪يٰ وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَآ أَصْبَرَهُمْ عَلَي اَ۬لنّ۪ارِۖ (174) ذَٰلِكَ بِأَنَّ اَ۬للَّهَ نَزَّلَ اَ۬لْكِتَٰبَ بِالْحَقِّۖ وَإِنَّ اَ۬لذِينَ اَ۪خْتَلَفُواْ فِے اِ۬لْكِتَٰبِ لَفِے شِقَاقِۢ بَعِيدٖۖ (175) ۞لَّيْسَ اَ۬لْبِرُّ أَن تُوَلُّواْ وُجُوهَكُمْ قِبَلَ اَ۬لْمَشْرِقِ وَالْمَغْرِبِ وَلَٰكِنِ اِ۬لْبِرُّ مَنَ اٰمَنَ بِاللَّهِ وَالْيَوْمِ اِ۬لَاخِرِ وَالْمَلَٰٓئِكَةِ وَالْكِتَٰبِ وَالنَّبِيٓـِٕۧنَ وَءَاتَي اَ۬لْمَالَ عَلَيٰ حُبِّهِۦ ذَوِے اِ۬لْقُرْب۪يٰ وَالْيَتَٰم۪يٰ وَالْمَسَٰكِينَ وَابْنَ اَ۬لسَّبِيلِ وَالسَّآئِلِينَ وَفِے اِ۬لرِّقَابِ وَأَقَامَ اَ۬لصَّلَوٰةَ وَءَاتَي اَ۬لزَّكَوٰةَ وَالْمُوفُونَ بِعَهْدِهِمُۥٓ إِذَا عَٰهَدُواْۖ وَالصَّٰبِرِينَ فِے اِ۬لْبَأْسَآءِ وَالضَّرَّآءِ وَحِينَ اَ۬لْبَأْسِۖ أُوْلَٰٓئِكَ اَ۬لذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ اُ۬لْمُتَّقُونَۖ (176) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ كُتِبَ عَلَيْكُمُ اُ۬لْقِصَاصُ فِے اِ۬لْقَتْلَيۖ اَ۬لْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالُانث۪يٰ بِالُانث۪يٰۖ فَمَنْ عُفِيَ لَهُۥ مِنَ اَخِيهِ شَےْءٞ فَاتِّبَاعُۢ بِالْمَعْرُوفِ وَأَدَآءٌ اِلَيْهِ بِإِحْسَٰنٖۖ ذَٰلِكَ تَخْفِيفٞ مِّن رَّبِّكُمْ وَرَحْمَةٞۖ فَمَنِ اِ۪عْتَد۪يٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ اَلِيمٞۖ (177) وَلَكُمْ فِے اِ۬لْقِصَاصِ حَيَوٰةٞ يَٰٓأُوْلِے اِ۬لَالْبَٰبِ لَعَلَّكُمْ تَتَّقُونَۖ (178) كُتِبَ عَلَيْكُمُۥٓ إِذَا حَضَرَ أَحَدَكُمُ اُ۬لْمَوْتُ إِن تَرَكَ خَيْراً اِ۬لْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَالَاقْرَبِينَ بِالْمَعْرُوفِۖ حَقّاً عَلَي اَ۬لْمُتَّقِينَۖ (179) فَمَنۢ بَدَّلَهُۥ بَعْدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَي اَ۬لذِينَ يُبَدِّلُونَهُۥٓۖ إِنَّ اَ۬للَّهَ سَمِيعٌ عَلِيمٞۖ (180) فَمَنْ خَافَ مِن مُّوصٖ جَنَفاً اَوِ اِثْماٗ فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِۖ إِنَّ اَ۬للَّهَ غَفُورٞ رَّحِيمٞۖ (181) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ كُتِبَ عَلَيْكُمُ اُ۬لصِّيَامُ كَمَا كُتِبَ عَلَي اَ۬لذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ (182) أَيَّاماٗ مَّعْدُودَٰتٖۖ فَمَن كَانَ مِنكُم مَّرِيضاً اَوْ عَلَيٰ سَفَرٖ فَعِدَّةٞ مِّنَ اَيَّامٍ ا۟خَرَۖ وَعَلَي اَ۬لذِينَ يُطِيقُونَهُۥ فِدْيَةُ طَعَامِ مَسَٰكِينَۖ فَمَن تَطَوَّعَ خَيْراٗ فَهُوَ خَيْرٞ لَّهُۥۖ وَأَن تَصُومُواْ خَيْرٞ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَۖ (183) ۞شَهْرُ رَمَضَانَ اَ۬لذِےٓ أُنزِلَ فِيهِ اِ۬لْقُرْءَانُ هُديٗ لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ اَ۬لْهُد۪يٰ وَالْفُرْقَانِۖ فَمَن شَهِدَ مِنكُمُ اُ۬لشَّهْرَ فَلْيَصُمْهُۖ وَمَن كَانَ مَرِيضاً اَوْ عَلَيٰ سَفَرٖ فَعِدَّةٞ مِّنَ اَيَّامٍ ا۟خَرَۖ يُرِيدُ اُ۬للَّهُ بِكُمُ اُ۬لْيُسْرَ وَلَا يُرِيدُ بِكُمُ اُ۬لْعُسْرَۖ وَلِتُكْمِلُواْ اُ۬لْعِدَّةَ وَلِتُكَبِّرُواْ اُ۬للَّهَ عَلَيٰ مَا هَد۪يٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَۖ (184) وَإِذَا سَأَلَكَ عِبَادِے عَنِّے فَإِنِّے قَرِيبٌۖ ا۟جِيبُ دَعْوَةَ اَ۬لدَّاعِۦٓ إِذَا دَعَانِۦۖ فَلْيَسْتَجِيبُواْ لِے وَلْيُومِنُواْ بِيَ لَعَلَّهُمْ يَرْشُدُونَۖ (185) أُحِلَّ لَكُمْ لَيْلَةَ اَ۬لصِّيَامِ اِ۬لرَّفَثُ إِلَيٰ نِسَآئِكُمْۖ هُنَّ لِبَاسٞ لَّكُمْ وَأَنتُمْ لِبَاسٞ لَّهُنَّۖ عَلِمَ اَ۬للَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْۖ فَالَٰنَ بَٰشِرُوهُنَّ وَابْتَغُواْ مَا كَتَبَ اَ۬للَّهُ لَكُمْۖ وَكُلُواْ وَاشْرَبُواْ حَتَّيٰ يَتَبَيَّنَ لَكُمُ اُ۬لْخَيْطُ اُ۬لَابْيَضُ مِنَ اَ۬لْخَيْطِ اِ۬لَاسْوَدِ مِنَ اَ۬لْفَجْرِۖ ثُمَّ أَتِمُّواْ اُ۬لصِّيَامَ إِلَي اَ۬ليْلِۖ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِے اِ۬لْمَسَٰجِدِۖ تِلْكَ حُدُودُ اُ۬للَّهِ فَلَا تَقْرَبُوهَاۖ كَذَٰلِكَ يُبَيِّنُ اُ۬للَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَۖ (186) وَلَا تَاكُلُوٓاْ أَمْوَٰلَكُم بَيْنَكُم بِالْبَٰطِلِ وَتُدْلُواْ بِهَآ إِلَي اَ۬لْحُكَّامِ لِتَاكُلُواْ فَرِيقاٗ مِّنَ اَمْوَٰلِ اِ۬لنَّاسِ بِالِاثْمِ وَأَنتُمْ تَعْلَمُونَۖ (187) ۞يَسْـَٔلُونَكَ عَنِ اِ۬لَاهِلَّةِۖ قُلْ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَالْحَجِّۖ وَلَيْسَ اَ۬لْبِرُّ بِأَن تَاتُواْ اُ۬لْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنِ اِ۬لْبِرُّ مَنِ اِ۪تَّق۪يٰۖ وَاتُواْ اُ۬لْبُيُوتَ مِنَ اَبْوَٰبِهَاۖ وَاتَّقُواْ اُ۬للَّهَ لَعَلَّكُمْ تُفْلِحُونَۖ (188) وَقَٰتِلُواْ فِے سَبِيلِ اِ۬للَّهِ اِ۬لذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓاْۖ إِنَّ اَ۬للَّهَ لَا يُحِبُّ اُ۬لْمُعْتَدِينَۖ (189) وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْۖ وَالْفِتْنَةُ أَشَدُّ مِنَ اَ۬لْقَتْلِۖ وَلَا تُقَٰتِلُوهُمْ عِندَ اَ۬لْمَسْجِدِ اِ۬لْحَرَامِ حَتَّيٰ يُقَٰتِلُوكُمْ فِيهِۖ فَإِن قَٰتَلُوكُمْ فَاقْتُلُوهُمْۖ كَذَٰلِكَ جَزَآءُ اُ۬لْكٰ۪فِرِينَۖ (190) فَإِنِ اِ۪نتَهَوْاْ فَإِنَّ اَ۬للَّهَ غَفُورٞ رَّحِيمٞۖ (191) وَقَٰتِلُوهُمْ حَتَّيٰ لَا تَكُونَ فِتْنَةٞ وَيَكُونَ اَ۬لدِّينُ لِلهِۖ فَإِنِ اِ۪نتَهَوْاْ فَلَا عُدْوَٰنَ إِلَّا عَلَي اَ۬لظَّٰلِمِينَۖ (192) اَ۬لشَّهْرُ اُ۬لْحَرَامُ بِالشَّهْرِ اِ۬لْحَرَامِ وَالْحُرُمَٰتُ قِصَاصٞۖ فَمَنِ اِ۪عْتَد۪يٰ عَلَيْكُمْ فَاعْتَدُواْ عَلَيْهِ بِمِثْلِ مَا اَ۪عْتَد۪يٰ عَلَيْكُمْۖ وَاتَّقُواْ اُ۬للَّهَ وَاعْلَمُوٓاْ أَنَّ اَ۬للَّهَ مَعَ اَ۬لْمُتَّقِينَۖ (193) وَأَنفِقُواْ فِے سَبِيلِ اِ۬للَّهِ وَلَا تُلْقُواْ بِأَيْدِيكُمُۥٓ إِلَي اَ۬لتَّهْلُكَةِ وَأَحْسِنُوٓاْۖ إِنَّ اَ۬للَّهَ يُحِبُّ اُ۬لْمُحْسِنِينَۖ (194) وَأَتِمُّواْ اُ۬لْحَجَّ وَالْعُمْرَةَ لِلهِۖ فَإِنُ ا۟حْصِرْتُمْ فَمَا اَ۪سْتَيْسَرَ مِنَ اَ۬لْهَدْيِۖ وَلَا تَحْلِقُواْ رُءُوسَكُمْ حَتَّيٰ يَبْلُغَ اَ۬لْهَدْيُ مَحِلَّهُۥۖ فَمَن كَانَ مِنكُم مَّرِيضاً اَوْ بِهِۦٓ أَذيٗ مِّن رَّأْسِهِۦ فَفِدْيَةٞ مِّن صِيَامٍ اَوْ صَدَقَةٍ اَوْ نُسُكٖۖ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِالْعُمْرَةِ إِلَي اَ۬لْحَجِّ فَمَا اَ۪سْتَيْسَرَ مِنَ اَ۬لْهَدْيِۖ ۞فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِے اِ۬لْحَجِّ وَسَبْعَةٍ اِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٞ كَامِلَةٞۖ ذَٰلِكَ لِمَن لَّمْ يَكُنَ اَهْلُهُۥ حَاضِرِے اِ۬لْمَسْجِدِ اِ۬لْحَرَامِۖ وَاتَّقُواْ اُ۬للَّهَ وَاعْلَمُوٓاْ أَنَّ اَ۬للَّهَ شَدِيدُ اُ۬لْعِقَابِۖ (195) اِ۬لْحَجُّ أَشْهُرٞ مَّعْلُومَٰتٞۖ فَمَن فَرَضَ فِيهِنَّ اَ۬لْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِے اِ۬لْحَجِّۖ وَمَا تَفْعَلُواْ مِنْ خَيْرٖ يَعْلَمْهُ اُ۬للَّهُۖ وَتَزَوَّدُواْ فَإِنَّ خَيْرَ اَ۬لزَّادِ اِ۬لتَّقْو۪يٰۖ وَاتَّقُونِ يَٰٓأُوْلِے اِ۬لَالْبَٰبِۖ (196) لَيْسَ عَلَيْكُمْ جُنَاحٌ اَن تَبْتَغُواْ فَضْلاٗ مِّن رَّبِّكُمْۖ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتٖ فَاذْكُرُواْ اُ۬للَّهَ عِندَ اَ۬لْمَشْعَرِ اِ۬لْحَرَامِۖ وَاذْكُرُوهُ كَمَا هَد۪يٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ اَ۬لضَّآلِّينَۖ (197) ثُمَّ أَفِيضُواْ مِنْ حَيْثُ أَفَاضَ اَ۬لنَّاسُۖ وَاسْتَغْفِرُواْ اُ۬للَّهَۖ إِنَّ اَ۬للَّهَ غَفُورٞ رَّحِيمٞۖ (198) فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَاذْكُرُواْ اُ۬للَّهَ كَذِكْرِكُمُۥٓ ءَابَآءَكُمُۥٓ أَوَ اَشَدَّ ذِكْراٗۖ فَمِنَ اَ۬لنَّاسِ مَنْ يَّقُولُ رَبَّنَآ ءَاتِنَا فِے اِ۬لدُّنْي۪ا وَمَا لَهُۥ فِے اِ۬لَاخِرَةِ مِنْ خَلَٰقٖۖ وَمِنْهُم مَّنْ يَّقُولُ رَبَّنَآ ءَاتِنَا فِے اِ۬لدُّنْي۪ا حَسَنَةٗ وَفِے اِ۬لَاخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ اَ۬لنّ۪ارِۖ (199) أُوْلَٰٓئِكَ لَهُمْ نَصِيبٞ مِّمَّا كَسَبُواْۖ وَاللَّهُ سَرِيعُ اُ۬لْحِسَابِۖ (200) ۞وَاذْكُرُواْ اُ۬للَّهَ فِےٓ أَيَّامٖ مَّعْدُودَٰتٖۖ فَمَن تَعَجَّلَ فِے يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ لِمَنِ اِ۪تَّق۪يٰۖ وَاتَّقُواْ اُ۬للَّهَ وَاعْلَمُوٓاْ أَنَّكُمُۥٓ إِلَيْهِ تُحْشَرُونَۖ (201) وَمِنَ اَ۬لنَّاسِ مَنْ يُّعْجِبُكَ قَوْلُهُۥ فِے اِ۬لْحَيَوٰةِ اِ۬لدُّنْي۪ا وَيُشْهِدُ اُ۬للَّهَ عَلَيٰ مَا فِے قَلْبِهِۦ وَهُوَ أَلَدُّ اُ۬لْخِصَامِۖ (202) وَإِذَا تَوَلّ۪يٰ سَع۪يٰ فِے اِ۬لَارْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ اَ۬لْحَرْثَ وَالنَّسْلَۖ وَاللَّهُ لَا يُحِبُّ اُ۬لْفَسَادَۖ (203) وَإِذَا قِيلَ لَهُ اُ۪تَّقِ اِ۬للَّهَ أَخَذَتْهُ اُ۬لْعِزَّةُ بِالِاثْمِۖ فَحَسْبُهُۥ جَهَنَّمُۖ وَلَبِيسَ اَ۬لْمِهَادُۖ (204) وَمِنَ اَ۬لنَّاسِ مَنْ يَّشْرِے نَفْسَهُ اُ۪بْتِغَآءَ مَرْضَاتِ اِ۬للَّهِۖ وَاللَّهُ رَءُوفُۢ بِالْعِبَادِۖ (205) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ اُ۟دْخُلُواْ فِے اِ۬لسَّلْمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطْوَٰتِ اِ۬لشَّيْطَٰنِۖ إِنَّهُۥ لَكُمْ عَدُوّٞ مُّبِينٞۖ (206) فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ اُ۬لْبَيِّنَٰتُ فَاعْلَمُوٓاْ أَنَّ اَ۬للَّهَ عَزِيزٌ حَكِيمٌۖ (207) هَلْ يَنظُرُونَ إِلَّآ أَنْ يَّاتِيَهُمُ اُ۬للَّهُ فِے ظُلَلٖ مِّنَ اَ۬لْغَمَٰمِ وَالْمَلَٰٓئِكَةُ وَقُضِيَ اَ۬لَامْرُۖ وَإِلَي اَ۬للَّهِ تُرْجَعُ اُ۬لُامُورُۖ (208) سَلْ بَنِےٓ إِسْرَآءِيلَ كَمَ اٰتَيْنَٰهُم مِّنَ اٰيَةِۢ بَيِّنَةٖۖ وَمَنْ يُّبَدِّلْ نِعْمَةَ اَ۬للَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ اَ۬للَّهَ شَدِيدُ اُ۬لْعِقَابِۖ (209) زُيِّنَ لِلذِينَ كَفَرُواْ اُ۬لْحَيَوٰةُ اُ۬لدُّنْي۪ا وَيَسْخَرُونَ مِنَ اَ۬لذِينَ ءَامَنُواْۖ وَالذِينَ اَ۪تَّقَوْاْ فَوْقَهُمْ يَوْمَ اَ۬لْقِيَٰمَةِۖ وَاللَّهُ يَرْزُقُ مَنْ يَّشَآءُ بِغَيْرِ حِسَابٖۖ (210) ۞كَانَ اَ۬لنَّاسُ أُمَّةٗ وَٰحِدَةٗ فَبَعَثَ اَ۬للَّهُ اُ۬لنَّبِيٓـِٕۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ اُ۬لْكِتَٰبَ بِالْحَقِّ لِيَحْكُمَ بَيْنَ اَ۬لنَّاسِ فِيمَا اَ۪خْتَلَفُواْ فِيهِۖ وَمَا اَ۪خْتَلَفَ فِيهِ إِلَّا اَ۬لذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ اُ۬لْبَيِّنَٰتُ بَغْياَۢ بَيْنَهُمْۖ فَهَدَي اَ۬للَّهُ اُ۬لذِينَ ءَامَنُواْ لِمَا اَ۪خْتَلَفُواْ فِيهِ مِنَ اَ۬لْحَقِّ بِإِذْنِهِۦۖ وَاللَّهُ يَهْدِے مَنْ يَّشَآءُ اِ۪لَيٰ صِرَٰطٖ مُّسْتَقِيمٍۖ (211) اَمْ حَسِبْتُمُۥٓ أَن تَدْخُلُواْ اُ۬لْجَنَّةَ وَلَمَّا يَاتِكُم مَّثَلُ اُ۬لذِينَ خَلَوْاْ مِن قَبْلِكُم مَّسَّتْهُمُ اُ۬لْبَأْسَآءُ وَالضَّرَّآءُ وَزُلْزِلُواْ حَتَّيٰ يَقُولُ اُ۬لرَّسُولُ وَالذِينَ ءَامَنُواْ مَعَهُۥ مَت۪يٰ نَصْرُ اُ۬للَّهِۖ أَلَآ إِنَّ نَصْرَ اَ۬للَّهِ قَرِيبٞۖ (212) يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٖ فَلِلْوَٰلِدَيْنِ وَالَاقْرَبِينَ وَالْيَتَٰم۪يٰ وَالْمَسَٰكِينِ وَابْنِ اِ۬لسَّبِيلِۖ وَمَا تَفْعَلُواْ مِنْ خَيْرٖ فَإِنَّ اَ۬للَّهَ بِهِۦ عَلِيمٞۖ (213) كُتِبَ عَلَيْكُمُ اُ۬لْقِتَالُ وَهُوَ كُرْهٞ لَّكُمْۖ وَعَس۪يٰٓ أَن تَكْرَهُواْ شَيْـٔاٗ وَهُوَ خَيْرٞ لَّكُمْۖ وَعَس۪يٰٓ أَن تُحِبُّواْ شَيْـٔاٗ وَهُوَ شَرّٞ لَّكُمْۖ وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَۖ (214) يَسْـَٔلُونَكَ عَنِ اِ۬لشَّهْرِ اِ۬لْحَرَامِ قِتَالٖ فِيهِۖ قُلْ قِتَالٞ فِيهِ كَبِيرٞۖ وَصَدٌّ عَن سَبِيلِ اِ۬للَّهِ وَكُفْرُۢ بِهِۦ وَالْمَسْجِدِ اِ۬لْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ اَ۬للَّهِۖ وَالْفِتْنَةُ أَكْبَرُ مِنَ اَ۬لْقَتْلِۖ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمْ حَتَّيٰ يَرُدُّوكُمْ عَن دِينِكُمُۥٓ إِنِ اِ۪سْتَطَٰعُواْۖ وَمَنْ يَّرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٞ فَأُوْلَٰٓئِكَ حَبِطَتَ اَعْمَٰلُهُمْ فِے اِ۬لدُّنْي۪ا وَالَاخِرَةِۖ وَأُوْلَٰٓئِكَ أَصْحَٰبُ اُ۬لنّ۪ارِ هُمْ فِيهَا خَٰلِدُونَۖ (215) إِنَّ اَ۬لذِينَ ءَامَنُواْ وَالذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِے سَبِيلِ اِ۬للَّهِ أُوْلَٰٓئِكَ يَرْجُونَ رَحْمَتَ اَ۬للَّهِۖ وَاللَّهُ غَفُورٞ رَّحِيمٞۖ (216) ۞يَسْـَٔلُونَكَ عَنِ اِ۬لْخَمْرِ وَالْمَيْسِرِۖ قُلْ فِيهِمَآ إِثْمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَاۖ وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ اِ۬لْعَفْوَۖ كَذَٰلِكَ يُبَيِّنُ اُ۬للَّهُ لَكُمُ اُ۬لَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ (217) فِے اِ۬لدُّنْي۪ا وَالَاخِرَةِۖ وَيَسْـَٔلُونَكَ عَنِ اِ۬لْيَتَٰم۪يٰ قُلِ اِصْلَٰحٞ لَّهُمْ خَيْرٞۖ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْۖ وَاللَّهُ يَعْلَمُ اُ۬لْمُفْسِدَ مِنَ اَ۬لْمُصْلِحِۖ وَلَوْ شَآءَ اَ۬للَّهُ لَأَعْنَتَكُمُۥٓۖ إِنَّ اَ۬للَّهَ عَزِيزٌ حَكِيمٞۖ (218) وَلَا تَنكِحُواْ اُ۬لْمُشْرِكَٰتِ حَتَّيٰ يُومِنَّۖ وَلَأَمَةٞ مُّومِنَةٌ خَيْرٞ مِّن مُّشْرِكَةٖ وَلَوَ اَعْجَبَتْكُمْۖ وَلَا تُنكِحُواْ اُ۬لْمُشْرِكِينَ حَتَّيٰ يُومِنُواْۖ وَلَعَبْدٞ مُّومِنٌ خَيْرٞ مِّن مُّشْرِكٖ وَلَوَ اَعْجَبَكُمُۥٓۖ أُوْلَٰٓئِكَ يَدْعُونَ إِلَي اَ۬لنّ۪ارِۖ وَاللَّهُ يَدْعُوٓاْ إِلَي اَ۬لْجَنَّةِ وَالْمَغْفِرَةِ بِإِذْنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَۖ (219) وَيَسْـَٔلُونَكَ عَنِ اِ۬لْمَحِيضِ قُلْ هُوَ أَذيٗ فَاعْتَزِلُواْ اُ۬لنِّسَآءَ فِے اِ۬لْمَحِيضِۖ وَلَا تَقْرَبُوهُنَّ حَتَّيٰ يَطْهُرْنَۖ فَإِذَا تَطَهَّرْنَ فَاتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اُ۬للَّهُۖ إِنَّ اَ۬للَّهَ يُحِبُّ اُ۬لتَّوَّٰبِينَ وَيُحِبُّ اُ۬لْمُتَطَهِّرِينَۖ (220) نِسَآؤُكُمْ حَرْثٞ لَّكُمْ فَاتُواْ حَرْثَكُمُۥٓ أَنّ۪يٰ شِئْتُمْۖ وَقَدِّمُواْ لِأَنفُسِكُمْۖ وَاتَّقُواْ اُ۬للَّهَ وَاعْلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۖ وَبَشِّرِ اِ۬لْمُومِنِينَۖ (221) وَلَا تَجْعَلُواْ اُ۬للَّهَ عُرْضَةٗ لِّأَيْمَٰنِكُمُۥٓ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصْلِحُواْ بَيْنَ اَ۬لنَّاسِۖ وَاللَّهُ سَمِيعٌ عَلِيمٞۖ (222) لَّا يُوَ۬اخِذُكُمُ اُ۬للَّهُ بِاللَّغْوِ فِےٓ أَيْمَٰنِكُمْ وَلَٰكِنْ يُّوَ۬اخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْۖ وَاللَّهُ غَفُورٌ حَلِيمٞۖ (223) لِّلذِينَ يُولُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٖۖ فَإِن فَآءُو فَإِنَّ اَ۬للَّهَ غَفُورٞ رَّحِيمٞۖ (224) وَإِنْ عَزَمُواْ اُ۬لطَّلَٰقَ فَإِنَّ اَ۬للَّهَ سَمِيعٌ عَلِيمٞۖ (225) ۞وَالْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۖ وَلَا يَحِلُّ لَهُنَّ أَنْ يَّكْتُمْنَ مَا خَلَقَ اَ۬للَّهُ فِےٓ أَرْحَامِهِنَّ إِن كُنَّ يُومِنَّ بِاللَّهِ وَالْيَوْمِ اِ۬لَاخِرِۖ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِے ذَٰلِكَ إِنَ اَرَادُوٓاْ إِصْلَٰحاٗۖ وَلَهُنَّ مِثْلُ اُ۬لذِے عَلَيْهِنَّ بِالْمَعْرُوفِۖ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٞۖ وَاللَّهُ عَزِيزٌ حَكِيمٌۖ (226) اِ۬لطَّلَٰقُ مَرَّتَٰنِۖ فَإِمْسَاكُۢ بِمَعْرُوفٍ اَوْ تَسْرِيحُۢ بِإِحْسَٰنٖۖ وَلَا يَحِلُّ لَكُمُۥٓ أَن تَاخُذُواْ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـٔاٗ اِلَّآ أَنْ يَّخَافَآ أَلَّا يُقِيمَا حُدُودَ اَ۬للَّهِۖ فَإِنْ خِفْتُمُۥٓ أَلَّا يُقِيمَا حُدُودَ اَ۬للَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا اَ۪فْتَدَتْ بِهِۦۖ تِلْكَ حُدُودُ اُ۬للَّهِ فَلَا تَعْتَدُوهَاۖ وَمَنْ يَّتَعَدَّ حُدُودَ اَ۬للَّهِ فَأُوْلَٰٓئِكَ هُمُ اُ۬لظَّٰلِمُونَۖ (227) فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّيٰ تَنكِحَ زَوْجاً غَيْرَهُۥۖ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَنْ يَّتَرَاجَعَآ إِن ظَنَّآ أَنْ يُّقِيمَا حُدُودَ اَ۬للَّهِۖ وَتِلْكَ حُدُودُ اُ۬للَّهِ يُبَيِّنُهَا لِقَوْمٖ يَعْلَمُونَۖ (228) وَإِذَا طَلَّقْتُمُ اُ۬لنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ اَوْ سَرِّحُوهُنَّ بِمَعْرُوفٖۖ وَلَا تُمْسِكُوهُنَّ ضِرَاراٗ لِّتَعْتَدُواْۖ وَمَنْ يَّفْعَلْ ذَٰلِكَ فَقَد ظَّلَمَ نَفْسَهُۥۖ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ اِ۬للَّهِ هُزُؤاٗۖ وَاذْكُرُواْ نِعْمَتَ اَ۬للَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ اَ۬لْكِتَٰبِ وَالْحِكْمَةِ يَعِظُكُم بِهِۦۖ وَاتَّقُواْ اُ۬للَّهَ وَاعْلَمُوٓاْ أَنَّ اَ۬للَّهَ بِكُلِّ شَےْءٍ عَلِيمٞۖ (229) وَإِذَا طَلَّقْتُمُ اُ۬لنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَنْ يَّنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْاْ بَيْنَهُم بِالْمَعْرُوفِۖ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُومِنُ بِاللَّهِ وَالْيَوْمِ اِ۬لَاخِرِۖ ذَٰلِكُمُۥٓ أَزْك۪يٰ لَكُمْ وَأَطْهَرُۖ وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَۖ (230) ۞وَالْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِۖ لِمَنَ اَرَادَ أَنْ يُّتِمَّ اَ۬لرَّضَٰعَةَۖ وَعَلَي اَ۬لْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِۖ لَا تُكَلَّفُ نَفْسٌ اِلَّا وُسْعَهَاۖ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوْلُودٞ لَّهُۥ بِوَلَدِهِۦۖ وَعَلَي اَ۬لْوَارِثِ مِثْلُ ذَٰلِكَۖ فَإِنَ اَرَادَا فِصَالاً عَن تَرَاضٖ مِّنْهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيْهِمَاۖ وَإِنَ اَرَدتُّمُۥٓ أَن تَسْتَرْضِعُوٓاْ أَوْلَٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمُۥٓ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِالْمَعْرُوفِۖ وَاتَّقُواْ اُ۬للَّهَ وَاعْلَمُوٓاْ أَنَّ اَ۬للَّهَ بِمَا تَعْمَلُونَ بَصِيرٞۖ (231) وَالذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجاٗ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٖ وَعَشْراٗۖ فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِےٓ أَنفُسِهِنَّ بِالْمَعْرُوفِۖ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٞۖ (232) وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ اِ۬لنِّسَآءِ اَ۬وَ اَكْنَنتُمْ فِےٓ أَنفُسِكُمْۖ عَلِمَ اَ۬للَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرّاً اِلَّآ أَن تَقُولُواْ قَوْلاٗ مَّعْرُوفاٗۖ ۞وَلَا تَعْزِمُواْ عُقْدَةَ اَ۬لنِّكَاحِ حَتَّيٰ يَبْلُغَ اَ۬لْكِتَٰبُ أَجَلَهُۥۖ وَاعْلَمُوٓاْ أَنَّ اَ۬للَّهَ يَعْلَمُ مَا فِےٓ أَنفُسِكُمْ فَاحْذَرُوهُۖ وَاعْلَمُوٓاْ أَنَّ اَ۬للَّهَ غَفُورٌ حَلِيمٞۖ (233) لَّا جُنَاحَ عَلَيْكُمُۥٓ إِن طَلَّقْتُمُ اُ۬لنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُواْ لَهُنَّ فَرِيضَةٗۖ وَمَتِّعُوهُنَّ عَلَي اَ۬لْمُوسِعِ قَدْرُهُۥ وَعَلَي اَ۬لْمُقْتِرِ قَدْرُهُۥ مَتَٰعاَۢ بِالْمَعْرُوفِۖ حَقّاً عَلَي اَ۬لْمُحْسِنِينَۖ (234) وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةٗ فَنِصْفُ مَا فَرَضْتُمُۥٓ إِلَّآ أَنْ يَّعْفُونَ أَوْ يَعْفُوَاْ اَ۬لذِے بِيَدِهِۦ عُقْدَةُ اُ۬لنِّكَاحِۖ وَأَن تَعْفُوٓاْ أَقْرَبُ لِلتَّقْو۪يٰۖ وَلَا تَنسَوُاْ اُ۬لْفَضْلَ بَيْنَكُمُۥٓۖ إِنَّ اَ۬للَّهَ بِمَا تَعْمَلُونَ بَصِيرٌۖ (235) حَٰفِظُواْ عَلَي اَ۬لصَّلَوَٰتِ وَالصَّلَوٰةِ اِ۬لْوُسْط۪يٰ وَقُومُواْ لِلهِ قَٰنِتِينَۖ (236) فَإِنْ خِفْتُمْ فَرِجَالاً اَوْ رُكْبَاناٗۖ فَإِذَآ أَمِنتُمْ فَاذْكُرُواْ اُ۬للَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُواْ تَعْلَمُونَۖ (237) وَالذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجاٗ وَصِيَّةٞ لِّأَزْوَٰجِهِم مَّتَٰعاً اِلَي اَ۬لْحَوْلِ غَيْرَ إِخْرَاجٖۖ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِے مَا فَعَلْنَ فِےٓ أَنفُسِهِنَّ مِن مَّعْرُوفٖۖ وَاللَّهُ عَزِيزٌ حَكِيمٞۖ (238) وَلِلْمُطَلَّقَٰتِ مَتَٰعُۢ بِالْمَعْرُوفِۖ حَقّاً عَلَي اَ۬لْمُتَّقِينَۖ (239) كَذَٰلِكَ يُبَيِّنُ اُ۬للَّهُ لَكُمُۥٓ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَۖ (240) ۞أَلَمْ تَرَ إِلَي اَ۬لذِينَ خَرَجُواْ مِن دِيٰ۪رِهِمْ وَهُمُۥٓ أُلُوفٌ حَذَرَ اَ۬لْمَوْتِ فَقَالَ لَهُمُ اُ۬للَّهُ مُوتُواْ ثُمَّ أَحْي۪اهُمُۥٓۖ إِنَّ اَ۬للَّهَ لَذُو فَضْلٍ عَلَي اَ۬لنَّاسِ وَلَٰكِنَّ أَكْثَرَ اَ۬لنَّاسِ لَا يَشْكُرُونَۖ (241) وَقَٰتِلُواْ فِے سَبِيلِ اِ۬للَّهِ وَاعْلَمُوٓاْ أَنَّ اَ۬للَّهَ سَمِيعٌ عَلِيمٞۖ (242) مَّن ذَا اَ۬لذِے يُقْرِضُ اُ۬للَّهَ قَرْضاً حَسَناٗ فَيُضَٰعِفُهُۥ لَهُۥٓ أَضْعَافاٗ كَثِيرَةٗۖ وَاللَّهُ يَقْبِضُ وَيَبْصُطُۖ وَإِلَيْهِ تُرْجَعُونَۖ (243) أَلَمْ تَرَ إِلَي اَ۬لْمَلَإِ مِنۢ بَنِےٓ إِسْرَآءِيلَ مِنۢ بَعْدِ مُوس۪يٰٓ إِذْ قَالُواْ لِنَبِےٓءٖ لَّهُمُ اُ۪بْعَثْ لَنَا مَلِكاٗ نُّقَٰتِلْ فِے سَبِيلِ اِ۬للَّهِۖ قَالَ هَلْ عَسِيتُمُۥٓ إِن كُتِبَ عَلَيْكُمُ اُ۬لْقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِے سَبِيلِ اِ۬للَّهِ وَقَدُ ا۟خْرِجْنَا مِن دِيٰ۪رِنَا وَأَبْنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيْهِمُ اُ۬لْقِتَالُ تَوَلَّوِاْ اِلَّا قَلِيلاٗ مِّنْهُمْۖ وَاللَّهُ عَلِيمُۢ بِالظَّٰلِمِينَۖ (244) وَقَالَ لَهُمْ نَبِيٓـُٔهُمُۥٓ إِنَّ اَ۬للَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكاٗۖ قَالُوٓاْ أَنّ۪يٰ يَكُونُ لَهُ اُ۬لْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُوتَ سَعَةٗ مِّنَ اَ۬لْمَالِۖ قَالَ إِنَّ اَ۬للَّهَ اَ۪صْطَف۪يٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةٗ فِے اِ۬لْعِلْمِ وَالْجِسْمِۖ وَاللَّهُ يُوتِے مُلْكَهُۥ مَنْ يَّشَآءُۖ وَاللَّهُ وَٰسِعٌ عَلِيمٞۖ (245) ۞وَقَالَ لَهُمْ نَبِيٓـُٔهُمُۥٓ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَنْ يَّاتِيَكُمُ اُ۬لتَّابُوتُ فِيهِ سَكِينَةٞ مِّن رَّبِّكُمْ وَبَقِيَّةٞ مِّمَّا تَرَكَ ءَالُ مُوس۪يٰ وَءَالُ هَٰرُونَ تَحْمِلُهُ اُ۬لْمَلَٰٓئِكَةُۖ إِنَّ فِے ذَٰلِكَ لَأٓيَةٗ لَّكُمُۥٓ إِن كُنتُم مُّومِنِينَۖ (246) فَلَمَّا فَصَلَ طَالُوتُ بِالْجُنُودِ قَالَ إِنَّ اَ۬للَّهَ مُبْتَلِيكُم بِنَهَرٖ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّے وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّيَ إِلَّا مَنِ اِ۪غْتَرَفَ غَرْفَةَۢ بِيَدِهِۦۖ فَشَرِبُواْ مِنْهُ إِلَّا قَلِيلاٗ مِّنْهُمْۖ فَلَمَّا جَاوَزَهُۥ هُوَ وَالذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا اَ۬لْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦۖ قَالَ اَ۬لذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ اُ۬للَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتْ فِئَةٗ كَثِيرَةَۢ بِإِذْنِ اِ۬للَّهِۖ وَاللَّهُ مَعَ اَ۬لصَّٰبِرِينَۖ (247) وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْراٗ وَثَبِّتَ اَقْدَامَنَا وَانصُرْنَا عَلَي اَ۬لْقَوْمِ اِ۬لْكٰ۪فِرِينَ (248) فَهَزَمُوهُم بِإِذْنِ اِ۬للَّهِۖ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَات۪يٰهُ اُ۬للَّهُ اُ۬لْمُلْكَ وَالْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۖ وَلَوْلَا دِفَٰعُ اُ۬للَّهِ اِ۬لنَّاسَ بَعْضَهُم بِبَعْضٖ لَّفَسَدَتِ اِ۬لَارْضُ وَلَٰكِنَّ اَ۬للَّهَ ذُو فَضْلٍ عَلَي اَ۬لْعَٰلَمِينَۖ (249) تِلْكَ ءَايَٰتُ اُ۬للَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّۖ وَإِنَّكَ لَمِنَ اَ۬لْمُرْسَلِينَۖ (250) ۞تِلْكَ اَ۬لرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَيٰ بَعْضٖۖ مِّنْهُم مَّن كَلَّمَ اَ۬للَّهُۖ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتٖۖ وَءَاتَيْنَا عِيسَي اَ۪بْنَ مَرْيَمَ اَ۬لْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ اِ۬لْقُدُسِۖ وَلَوْ شَآءَ اَ۬للَّهُ مَا اَ۪قْتَتَلَ اَ۬لذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ اُ۬لْبَيِّنَٰتُ وَلَٰكِنِ اِ۪خْتَلَفُواْۖ فَمِنْهُم مَّنَ اٰمَنَ وَمِنْهُم مَّن كَفَرَۖ وَلَوْ شَآءَ اَ۬للَّهُ مَا اَ۪قْتَتَلُواْ وَلَٰكِنَّ اَ۬للَّهَ يَفْعَلُ مَا يُرِيدُۖ (251) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَنْ يَّاتِيَ يَوْمٞ لَّا بَيْعٞ فِيهِ وَلَا خُلَّةٞ وَلَا شَفَٰعَةٞۖ وَالْكَٰفِرُونَ هُمُ اُ۬لظَّٰلِمُونَۖ (252) اَ۬للَّهُ لَآ إِلَٰهَ إِلَّا هُوَ اَ۬لْحَيُّ اُ۬لْقَيُّومُۖ (253) لَا تَاخُذُهُۥ سِنَةٞ وَلَا نَوْمٞۖ لَّهُۥ مَا فِے اِ۬لسَّمَٰوَٰتِ وَمَا فِے اِ۬لَارْضِۖ مَن ذَا اَ۬لذِے يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦۖ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْۖ وَلَا يُحِيطُونَ بِشَےْءٖ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَۖ وَسِعَ كُرْسِيُّهُ اُ۬لسَّمَٰوَٰتِ وَالَارْضَۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَاۖ وَهُوَ اَ۬لْعَلِيُّ اُ۬لْعَظِيمُۖ (254) لَآ إِكْرَاهَ فِے اِ۬لدِّينِۖ قَد تَّبَيَّنَ اَ۬لرُّشْدُ مِنَ اَ۬لْغَيِّۖ فَمَنْ يَّكْفُرْ بِالطَّٰغُوتِ وَيُومِنۢ بِاللَّهِ فَقَدِ اِ۪سْتَمْسَكَ بِالْعُرْوَةِ اِ۬لْوُثْق۪يٰ لَا اَ۪نفِصَامَ لَهَاۖ وَاللَّهُ سَمِيعٌ عَلِيمٌۖ (255) اِ۬للَّهُ وَلِيُّ اُ۬لذِينَ ءَامَنُواْ يُخْرِجُهُم مِّنَ اَ۬لظُّلُمَٰتِ إِلَي اَ۬لنُّورِۖ وَالذِينَ كَفَرُوٓاْ أَوْلِيَآؤُهُمُ اُ۬لطَّٰغُوتُ يُخْرِجُونَهُم مِّنَ اَ۬لنُّورِ إِلَي اَ۬لظُّلُمَٰتِۖ أُوْلَٰٓئِكَ أَصْحَٰبُ اُ۬لنّ۪ارِ هُمْ فِيهَا خَٰلِدُونَۖ (256) ۞أَلَمْ تَرَ إِلَي اَ۬لذِے حَآجَّ إِبْرَٰهِيمَ فِے رَبِّهِۦٓ أَنَ اٰت۪يٰهُ اُ۬للَّهُ اُ۬لْمُلْكَ إِذْ قَالَ إِبْرَٰهِيمُ رَبِّيَ اَ۬لذِے يُحْيِۦ وَيُمِيتُۖ قَالَ أَنَآ أُحْيِۦ وَأُمِيتُۖ قَالَ إِبْرَٰهِيمُ فَإِنَّ اَ۬للَّهَ يَاتِے بِالشَّمْسِ مِنَ اَ۬لْمَشْرِقِ فَاتِ بِهَا مِنَ اَ۬لْمَغْرِبِ فَبُهِتَ اَ۬لذِے كَفَرَۖ وَاللَّهُ لَا يَهْدِے اِ۬لْقَوْمَ اَ۬لظَّٰلِمِينَۖ (257) أَوْ كَالذِے مَرَّ عَلَيٰ قَرْيَةٖ وَهِيَ خَاوِيَةٌ عَلَيٰ عُرُوشِهَاۖ قَالَ أَنّ۪يٰ يُحْيِۦ هَٰذِهِ اِ۬للَّهُ بَعْدَ مَوْتِهَاۖ فَأَمَاتَهُ اُ۬للَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمْ لَبِثْتَۖ قَالَ لَبِثْتُ يَوْماً اَوْ بَعْضَ يَوْمٖۖ قَالَ بَل لَّبِثْتَ مِاْئَةَ عَامٖۖ فَانظُرِ اِلَيٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْۖ وَانظُرِ اِلَيٰ حِم۪ارِكَ وَلِنَجْعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَانظُرِ اِلَي اَ۬لْعِظَٰمِ كَيْفَ نُنشِرُهَا ثُمَّ نَكْسُوهَا لَحْماٗۖ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ اَ۬للَّهَ عَلَيٰ كُلِّ شَےْءٖ قَدِيرٞۖ (258) وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ أَرِنِے كَيْفَ تُحْيِ اِ۬لْمَوْت۪يٰۖ قَالَ أَوَلَمْ تُومِنۖ قَالَ بَل۪يٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِےۖ قَالَ فَخُذَ اَرْبَعَةٗ مِّنَ اَ۬لطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ اَ۪جْعَلْ عَلَيٰ كُلِّ جَبَلٖ مِّنْهُنَّ جُزْءاٗ ثُمَّ اَ۟دْعُهُنَّ يَاتِينَكَ سَعْياٗۖ وَاعْلَمَ اَنَّ اَ۬للَّهَ عَزِيزٌ حَكِيمٞۖ (259) مَّثَلُ اُ۬لذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِے سَبِيلِ اِ۬للَّهِ كَمَثَلِ حَبَّةٍ اَنۢبَتَتْ سَبْعَ سَنَابِلَ فِے كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۖ وَاللَّهُ يُضَٰعِفُ لِمَنْ يَّشَآءُۖ وَاللَّهُ وَٰسِعٌ عَلِيمٌۖ (260) اِ۬لذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِے سَبِيلِ اِ۬للَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُواْ مَنّاٗ وَلَآ أَذيٗ لَّهُمُۥٓ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۖ (261) ۞قَوْلٞ مَّعْرُوفٞ وَمَغْفِرَةٌ خَيْرٞ مِّن صَدَقَةٖ يَتْبَعُهَآ أَذيٗۖ وَاللَّهُ غَنِيٌّ حَلِيمٞۖ (262) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ لَا تُبْطِلُواْ صَدَقَٰتِكُم بِالْمَنِّ وَالَاذ۪يٰ كَالذِے يُنفِقُ مَالَهُۥ رِئَآءَ اَ۬لنَّاسِ وَلَا يُومِنُ بِاللَّهِ وَالْيَوْمِ اِ۬لَاخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلْداٗۖ لَّا يَقْدِرُونَ عَلَيٰ شَےْءٖ مِّمَّا كَسَبُواْۖ وَاللَّهُ لَا يَهْدِے اِ۬لْقَوْمَ اَ۬لْكٰ۪فِرِينَۖ (263) وَمَثَلُ اُ۬لذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ اُ۪بْتِغَآءَ مَرْضَاتِ اِ۬للَّهِ وَتَثْبِيتاٗ مِّنَ اَنفُسِهِمْ كَمَثَلِ جَنَّةِۢ بِرُبْوَةٍ اَصَابَهَا وَابِلٞ فَـَٔاتَتُ ا۟كْلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٞ فَطَلّٞۖ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۖ (264) اَيَوَدُّ أَحَدُكُمُۥٓ أَن تَكُونَ لَهُۥ جَنَّةٞ مِّن نَّخِيلٖ وَأَعْنَٰبٖ تَجْرِے مِن تَحْتِهَا اَ۬لَانْهَٰرُ لَهُۥ فِيهَا مِن كُلِّ اِ۬لثَّمَرَٰتِ وَأَصَابَهُ اُ۬لْكِبَرُ وَلَهُۥ ذُرِّيَّةٞ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٞ فِيهِ نَارٞ فَاحْتَرَقَتْۖ كَذَٰلِكَ يُبَيِّنُ اُ۬للَّهُ لَكُمُ اُ۬لَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَۖ (265) ۞يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ اَ۬لَارْضِۖ وَلَا تَيَمَّمُواْ اُ۬لْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُواْ فِيهِۖ وَاعْلَمُوٓاْ أَنَّ اَ۬للَّهَ غَنِيٌّ حَمِيدٌۖ (266) اِ۬لشَّيْطَٰنُ يَعِدُكُمُ اُ۬لْفَقْرَ وَيَامُرُكُم بِالْفَحْشَآءِۖ وَاللَّهُ يَعِدُكُم مَّغْفِرَةٗ مِّنْهُ وَفَضْلاٗۖ وَاللَّهُ وَٰسِعٌ عَلِيمٞۖ (267) يُوتِے اِ۬لْحِكْمَةَ مَنْ يَّشَآءُۖ وَمَنْ يُّوتَ اَ۬لْحِكْمَةَ فَقَدُ ا۟وتِيَ خَيْراٗ كَثِيراٗۖ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ اُ۬لَالْبَٰبِۖ (268) وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ اَوْ نَذَرْتُم مِّن نَّذْرٖ فَإِنَّ اَ۬للَّهَ يَعْلَمُهُۥۖ وَمَا لِلظَّٰلِمِينَ مِنَ اَنص۪ارٍۖ (269) اِن تُبْدُواْ اُ۬لصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخْفُوهَا وَتُوتُوهَا اَ۬لْفُقَرَآءَ فَهُوَ خَيْرٞ لَّكُمْ وَنُكَفِّرْ عَنكُم مِّن سَيِّـَٔاتِكُمْۖ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٞۖ (270) ۞لَّيْسَ عَلَيْكَ هُد۪يٰهُمْ وَلَٰكِنَّ اَ۬للَّهَ يَهْدِے مَنْ يَّشَآءُۖ وَمَا تُنفِقُواْ مِنْ خَيْرٖ فَلِأَنفُسِكُمْۖ وَمَا تُنفِقُونَ إِلَّا اَ۪بْتِغَآءَ وَجْهِ اِ۬للَّهِۖ وَمَا تُنفِقُواْ مِنْ خَيْرٖ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَۖ (271) لِلْفُقَرَآءِ اِ۬لذِينَ أُحْصِرُواْ فِے سَبِيلِ اِ۬للَّهِ لَا يَسْتَطِيعُونَ ضَرْباٗ فِے اِ۬لَارْضِ يَحْسِبُهُمُ اُ۬لْجَاهِلُ أَغْنِيَآءَ مِنَ اَ۬لتَّعَفُّفِۖ تَعْرِفُهُم بِسِيمٰ۪هُمْ لَا يَسْـَٔلُونَ اَ۬لنَّاسَ إِلْحَافاٗۖ وَمَا تُنفِقُواْ مِنْ خَيْرٖ فَإِنَّ اَ۬للَّهَ بِهِۦ عَلِيمٌۖ (272) اِ۬لذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِاليْلِ وَالنَّه۪ارِ سِرّاٗ وَعَلَٰنِيَةٗ فَلَهُمُۥٓ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۖ (273) اَ۬لذِينَ يَاكُلُونَ اَ۬لرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ اُ۬لذِے يَتَخَبَّطُهُ اُ۬لشَّيْطَٰنُ مِنَ اَ۬لْمَسِّۖ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓاْ إِنَّمَا اَ۬لْبَيْعُ مِثْلُ اُ۬لرِّبَوٰاْۖ وَأَحَلَّ اَ۬للَّهُ اُ۬لْبَيْعَ وَحَرَّمَ اَ۬لرِّبَوٰاْۖ فَمَن جَآءَهُۥ مَوْعِظَةٞ مِّن رَّبِّهِۦ فَانتَه۪يٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَي اَ۬للَّهِۖ وَمَنْ عَادَ فَأُوْلَٰٓئِكَ أَصْحَٰبُ اُ۬لنّ۪ارِ هُمْ فِيهَا خَٰلِدُونَۖ (274) يَمْحَقُ اُ۬للَّهُ اُ۬لرِّبَوٰاْ وَيُرْبِے اِ۬لصَّدَقَٰتِۖ وَاللَّهُ لَا يُحِبُّ كُلَّ كَفّ۪ارٍ اَثِيمٍۖ (275) اِنَّ اَ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ اُ۬لصَّٰلِحَٰتِ وَأَقَامُواْ اُ۬لصَّلَوٰةَ وَءَاتَوُاْ اُ۬لزَّكَوٰةَ لَهُمُۥٓ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۖ (276) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ اُ۪تَّقُواْ اُ۬للَّهَ وَذَرُواْ مَا بَقِيَ مِنَ اَ۬لرِّبَوٰٓاْ إِن كُنتُم مُّومِنِينَۖ (277) فَإِن لَّمْ تَفْعَلُواْ فَاذَنُواْ بِحَرْبٖ مِّنَ اَ۬للَّهِ وَرَسُولِهِۦۖ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَۖ (278) ۞وَإِن كَانَ ذُو عُسْرَةٖ فَنَظِرَةٌ اِلَيٰ مَيْسُرَةٖۖ وَأَن تَصَّدَّقُواْ خَيْرٞ لَّكُمُۥٓۖ إِن كُنتُمْ تَعْلَمُونَۖ (279) وَاتَّقُواْ يَوْماٗ تُرْجَعُونَ فِيهِ إِلَي اَ۬للَّهِۖ ثُمَّ تُوَفّ۪يٰ كُلُّ نَفْسٖ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَۖ (280) يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيْنٍ اِلَيٰٓ أَجَلٖ مُّسَمّيٗ فَاكْتُبُوهُۖ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبُۢ بِالْعَدْلِۖ وَلَا يَابَ كَاتِبٌ اَنْ يَّكْتُبَۖ كَمَا عَلَّمَهُ اُ۬للَّهُ فَلْيَكْتُبْۖ وَلْيُمْلِلِ اِ۬لذِے عَلَيْهِ اِ۬لْحَقُّ وَلْيَتَّقِ اِ۬للَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـٔاٗۖ فَإِن كَانَ اَ۬لذِے عَلَيْهِ اِ۬لْحَقُّ سَفِيهاً اَوْ ضَعِيفاً اَوْ لَا يَسْتَطِيعُ أَنْ يُّمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِالْعَدْلِۖ وَاسْتَشْهِدُواْ شَهِيدَيْنِ مِن رِّجَالِكُمْۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٞ وَامْرَأَتَٰنِ مِمَّن تَرْضَوْنَ مِنَ اَ۬لشُّهَدَآءِ اَ۬ن تَضِلَّ إِحْد۪يٰهُمَا فَتُذَكِّرَ إِحْد۪يٰهُمَا اَ۬لُاخْر۪يٰۖ وَلَا يَابَ اَ۬لشُّهَدَآءُ اِ۪ذَا مَا دُعُواْۖ وَلَا تَسْـَٔمُوٓاْ أَن تَكْتُبُوهُ صَغِيراً اَوْ كَبِيراً اِلَيٰٓ أَجَلِهِۦۖ ذَٰلِكُمُۥٓ أَقْسَطُ عِندَ اَ۬للَّهِ وَأَقْوَمُ لِلشَّهَٰدَةِ وَأَدْن۪يٰٓ أَلَّا تَرْتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةٌ حَاضِرَةٞ تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ اَلَّا تَكْتُبُوهَاۖ وَأَشْهِدُوٓاْ إِذَا تَبَايَعْتُمْۖ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۖ وَإِن تَفْعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمْۖ وَاتَّقُواْ اُ۬للَّهَۖ وَيُعَلِّمُكُمُ اُ۬للَّهُۖ وَاللَّهُ بِكُلِّ شَےْءٍ عَلِيمٞۖ (281) ۞وَإِن كُنتُمْ عَلَيٰ سَفَرٖ وَلَمْ تَجِدُواْ كَاتِباٗ فَرِهَٰنٞ مَّقْبُوضَةٞۖ فَإِنَ اَمِنَ بَعْضُكُم بَعْضاٗ فَلْيُوَ۬دِّ اِ۬لذِے اِ۟وتُمِنَ أَمَٰنَتَهُۥ وَلْيَتَّقِ اِ۬للَّهَ رَبَّهُۥۖ وَلَا تَكْتُمُواْ اُ۬لشَّهَٰدَةَۖ وَمَنْ يَّكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلْبُهُۥۖ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٞۖ (282) لِّلهِ مَا فِے اِ۬لسَّمَٰوَٰتِ وَمَا فِے اِ۬لَارْضِۖ وَإِن تُبْدُواْ مَا فِےٓ أَنفُسِكُمُۥٓ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اِ۬للَّهُ فَيَغْفِرْ لِمَنْ يَّشَآءُ وَيُعَذِّبْ مَنْ يَّشَآءُۖ وَاللَّهُ عَلَيٰ كُلِّ شَےْءٖ قَدِيرٌۖ (283) اٰمَنَ اَ۬لرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَالْمُومِنُونَۖ كُلٌّ اٰمَنَ بِاللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦۖ لَا نُفَرِّقُ بَيْنَ أَحَدٖ مِّن رُّسُلِهِۦۖ وَقَالُواْ سَمِعْنَا وَأَطَعْنَاۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ اَ۬لْمَصِيرُۖ (284) لَا يُكَلِّفُ اُ۬للَّهُ نَفْساً اِلَّا وُسْعَهَاۖ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اَ۪كْتَسَبَتْۖ رَبَّنَا لَا تُوَ۬اخِذْنَآ إِن نَّسِينَآ أَوَ اَخْطَأْنَاۖ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْراٗ كَمَا حَمَلْتَهُۥ عَلَي اَ۬لذِينَ مِن قَبْلِنَاۖ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَآۖ أَنتَ مَوْل۪يٰنَا فَانصُرْنَا عَلَي اَ۬لْقَوْمِ اِ۬لْكٰ۪فِرِينَۖ (285)
',
