+++ بِسْمِ اِ۬للَّهِ اِ۬لرَّحْمَٰنِ اِ۬لرَّحِيمِ
اِ۬لْحَمْدُ لِلهِ اِ۬لذِے خَلَقَ اَ۬لسَّمَٰوَٰتِ وَالَارْضَ وَجَعَلَ اَ۬لظُّلُمَٰتِ وَالنُّورَ (1) ثُمَّ اَ۬لذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَۖ (2) هُوَ اَ۬لذِے خَلَقَكُم مِّن طِينٖ ثُمَّ قَض۪يٰٓ أَجَلاٗۖ وَأَجَلٞ مُّسَمّيً عِندَهُۥۖ ثُمَّ أَنتُمْ تَمْتَرُونَۖ (3) وَهُوَ اَ۬للَّهُ فِے اِ۬لسَّمَٰوَٰتِ وَفِے اِ۬لَارْضِ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَۖ (4) وَمَا تَاتِيهِم مِّنَ اٰيَةٖ مِّنَ اٰيَٰتِ رَبِّهِمُۥٓ إِلَّا كَانُواْ عَنْهَا مُعْرِضِينَۖ (5) فَقَدْ كَذَّبُواْ بِالْحَقِّ لَمَّا جَآءَهُمْۖ فَسَوْفَ يَاتِيهِمُۥٓ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسْتَهْزِءُونَۖ (6) أَلَمْ يَرَوْاْ كَمَ اَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٖ مَّكَّنَّٰهُمْ فِے اِ۬لَارْضِ مَا لَمْ نُمَكِّن لَّكُمْۖ وَأَرْسَلْنَا اَ۬لسَّمَآءَ عَلَيْهِم مِّدْرَاراٗ وَجَعَلْنَا اَ۬لَانْهَٰرَ تَجْرِے مِن تَحْتِهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْۖ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْناً اٰخَرِينَۖ (7) وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَٰباٗ فِے قِرْطَاسٖ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ اَ۬لذِينَ كَفَرُوٓاْ إِنْ هَٰذَآ إِلَّا سِحْرٞ مُّبِينٞۖ (8) وَقَالُواْ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٞۖ وَلَوَ اَنزَلْنَا مَلَكاٗ لَّقُضِيَ اَ۬لَامْرُ ثُمَّ لَا يُنظَرُونَۖ (9) وَلَوْ جَعَلْنَٰهُ مَلَكاٗ لَّجَعَلْنَٰهُ رَجُلاٗ وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَۖ (10) وَلَقَدُ اُ۟سْتُهْزِۓَ بِرُسُلٖ مِّن قَبْلِكَ فَحَاقَ بِالذِينَ سَخِرُواْ مِنْهُم مَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَۖ (11) قُلْ سِيرُواْ فِے اِ۬لَارْضِ ثُمَّ اَ۟نظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ اُ۬لْمُكَذِّبِينَۖ (12) قُل لِّمَن مَّا فِے اِ۬لسَّمَٰوَٰتِ وَالَارْضِ قُل لِّلهِۖ كَتَبَ عَلَيٰ نَفْسِهِ اِ۬لرَّحْمَةَۖ لَيَجْمَعَنَّكُمُۥٓ إِلَيٰ يَوْمِ اِ۬لْقِيَٰمَةِ لَا رَيْبَ فِيهِۖ اِ۬لذِينَ خَسِرُوٓاْ أَنفُسَهُمْ فَهُمْ لَا يُومِنُونَۖ (13) ۞وَلَهُۥ مَا سَكَنَ فِے اِ۬ليْلِ وَالنَّه۪ارِۖ وَهُوَ اَ۬لسَّمِيعُ اُ۬لْعَلِيمُۖ (14) قُلَ اَغَيْرَ اَ۬للَّهِ أَتَّخِذُ وَلِيّاٗ فَاطِرِ اِ۬لسَّمَٰوَٰتِ وَالَارْضِۖ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُۖ قُلِ اِنِّيَ أُمِرْتُ أَنَ اَكُونَ أَوَّلَ مَنَ اَسْلَمَۖ وَلَا تَكُونَنَّ مِنَ اَ۬لْمُشْرِكِينَۖ (15) قُلِ اِنِّيَ أَخَافُ إِنْ عَصَيْتُ رَبِّے عَذَابَ يَوْمٍ عَظِيمٖۖ (16) مَّنْ يُّصْرَفْ عَنْهُ يَوْمَئِذٖ فَقَدْ رَحِمَهُۥۖ وَذَٰلِكَ اَ۬لْفَوْزُ اُ۬لْمُبِينُۖ (17) وَإِنْ يَّمْسَسْكَ اَ۬للَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِنْ يَّمْسَسْكَ بِخَيْرٖ فَهُوَ عَلَيٰ كُلِّ شَےْءٖ قَدِيرٞۖ (18) وَهُوَ اَ۬لْقَاهِرُ فَوْقَ عِبَادِهِۦۖ وَهُوَ اَ۬لْحَكِيمُ اُ۬لْخَبِيرُۖ (19) قُلَ اَيُّ شَےْءٍ اَكْبَرُ شَهَٰدَةٗ قُلِ اِ۬للَّهُۖ شَهِيدُۢ بَيْنِے وَبَيْنَكُمْۖ وَأُوحِيَ إِلَيَّ هَٰذَا اَ۬لْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۖ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ اَ۬للَّهِ ءَالِهَةً ا۟خْر۪يٰ قُل لَّآ أَشْهَدُۖ قُلِ اِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَإِنَّنِے بَرِےٓءٞ مِّمَّا تُشْرِكُونَۖ (20) اَ۬لذِينَ ءَاتَيْنَٰهُمُ اُ۬لْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُۖ اُ۬لذِينَ خَسِرُوٓاْ أَنفُسَهُمْ فَهُمْ لَا يُومِنُونَۖ (21) وَمَنَ اَظْلَمُ مِمَّنِ اِ۪فْتَر۪يٰ عَلَي اَ۬للَّهِ كَذِباً اَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓۖ إِنَّهُۥ لَا يُفْلِحُ اُ۬لظَّٰلِمُونَۖ (22) وَيَوْمَ نَحْشُرُهُمْ جَمِيعاٗ ثُمَّ نَقُولُ لِلذِينَ أَشْرَكُوٓاْ أَيْنَ شُرَكَآؤُكُمُ اُ۬لذِينَ كُنتُمْ تَزْعُمُونَۖ (23) ثُمَّ لَمْ تَكُن فِتْنَتَهُمُۥٓ إِلَّآ أَن قَالُواْ وَاللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَۖ (24) اَ۟نظُرْ كَيْفَ كَذَبُواْ عَلَيٰٓ أَنفُسِهِمْ وَضَلَّ عَنْهُم مَّا كَانُواْ يَفْتَرُونَۖ (25) وَمِنْهُم مَّنْ يَّسْتَمِعُ إِلَيْكَۖ وَجَعَلْنَا عَلَيٰ قُلُوبِهِمُۥٓ أَكِنَّةً اَنْ يَّفْقَهُوهُ وَفِےٓ ءَاذَانِهِمْ وَقْراٗۖ وَإِنْ يَّرَوْاْ كُلَّ ءَايَةٖ لَّا يُومِنُواْ بِهَاۖ حَتَّيٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ اُ۬لذِينَ كَفَرُوٓاْ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ اُ۬لَاوَّلِينَۖ (26) ۞وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُۖ وَإِنْ يُّهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَۖ (27) وَلَوْ تَر۪يٰٓ إِذْ وُقِفُواْ عَلَي اَ۬لنّ۪ارِ فَقَالُواْ يَٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبُ بِـَٔايَٰتِ رَبِّنَا وَنَكُونُ مِنَ اَ۬لْمُومِنِينَۖ (28) بَلْ بَدَا لَهُم مَّا كَانُواْ يُخْفُونَ مِن قَبْلُۖ وَلَوْ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنْهُ وَإِنَّهُمْ لَكَٰذِبُونَۖ (29) وَقَالُوٓاْ إِنْ هِيَ إِلَّا حَيَاتُنَا اَ۬لدُّنْي۪ا وَمَا نَحْنُ بِمَبْعُوثِينَۖ (30) وَلَوْ تَر۪يٰٓ إِذْ وُقِفُواْ عَلَيٰ رَبِّهِمْ قَالَ أَلَيْسَ هَٰذَا بِالْحَقِّۖ قَالُواْ بَل۪يٰ وَرَبِّنَاۖ قَالَ فَذُوقُواْ اُ۬لْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَۖ (31) قَدْ خَسِرَ اَ۬لذِينَ كَذَّبُواْ بِلِقَآءِ اِ۬للَّهِ حَتَّيٰٓ إِذَا جَآءَتْهُمُ اُ۬لسَّاعَةُ بَغْتَةٗ قَالُواْ يَٰحَسْرَتَنَا عَلَيٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَيٰ ظُهُورِهِمُۥٓۖ أَلَا سَآءَ مَا يَزِرُونَۖ (32) وَمَا اَ۬لْحَيَوٰةُ اُ۬لدُّنْي۪آ إِلَّا لَعِبٞ وَلَهْوٞۖ وَلَلدَّارُ اُ۬لَاخِرَةُ خَيْرٞ لِّلذِينَ يَتَّقُونَۖ أَفَلَا تَعْقِلُونَۖ (33) قَدْ نَعْلَمُ إِنَّهُۥ لَيُحْزِنُكَ اَ۬لذِے يَقُولُونَۖ فَإِنَّهُمْ لَا يُكْذِبُونَكَ وَلَٰكِنَّ اَ۬لظَّٰلِمِينَ بِـَٔايَٰتِ اِ۬للَّهِ يَجْحَدُونَۖ (34) وَلَقَدْ كُذِّبَتْ رُسُلٞ مِّن قَبْلِكَ فَصَبَرُواْ عَلَيٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّيٰٓ أَت۪يٰهُمْ نَصْرُنَاۖ وَلَا مُبَدِّلَ لِكَلِمَٰتِ اِ۬للَّهِۖ وَلَقَدْ جَآءَكَ مِن نَّبَإِےْ اِ۬لْمُرْسَلِينَۖ (35) وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ اِ۪سْتَطَعْتَ أَن تَبْتَغِيَ نَفَقاٗ فِے اِ۬لَارْضِ أَوْ سُلَّماٗ فِے اِ۬لسَّمَآءِ فَتَاتِيَهُم بِـَٔايَةٖۖ وَلَوْ شَآءَ اَ۬للَّهُ لَجَمَعَهُمْ عَلَي اَ۬لْهُد۪يٰۖ فَلَا تَكُونَنَّ مِنَ اَ۬لْجَٰهِلِينَۖ (36) ۞إِنَّمَا يَسْتَجِيبُ اُ۬لذِينَ يَسْمَعُونَۖ وَالْمَوْت۪يٰ يَبْعَثُهُمُ اُ۬للَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَۖ (37) وَقَالُواْ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٞ مِّن رَّبِّهِۦۖ قُلِ اِنَّ اَ۬للَّهَ قَادِرٌ عَلَيٰٓ أَنْ يُّنَزِّلَ ءَايَةٗ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَۖ (38) وَمَا مِن دَآبَّةٖ فِے اِ۬لَارْضِ وَلَا طَٰٓئِرٖ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ اَمْثَالُكُمۖ مَّا فَرَّطْنَا فِے اِ۬لْكِتَٰبِ مِن شَےْءٖۖ ثُمَّ إِلَيٰ رَبِّهِمْ يُحْشَرُونَۖ (39) وَالذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا صُمّٞ وَبُكْمٞ فِے اِ۬لظُّلُمَٰتِۖ مَنْ يَّشَإِ اِ۬للَّهُ يُضْلِلْهُ وَمَنْ يَّشَأْ يَجْعَلْهُ عَلَيٰ صِرَٰطٖ مُّسْتَقِيمٖۖ (40) قُلَ اَرَٰٓيتَكُمُۥٓ إِنَ اَت۪يٰكُمْ عَذَابُ اُ۬للَّهِ أَوَ اَتَتْكُمُ اُ۬لسَّاعَةُ أَغَيْرَ اَ۬للَّهِ تَدْعُونَ إِن كُنتُمْ صَٰدِقِينَۖ (41) بَلِ اِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَۖ (42) وَلَقَدَ اَرْسَلْنَآ إِلَيٰٓ أُمَمٖ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِالْبَأْسَآءِ وَالضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَۖ (43) فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ اُ۬لشَّيْطَٰنُ مَا كَانُواْ يَعْمَلُونَۖ (44) فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحْنَا عَلَيْهِمُۥٓ أَبْوَٰبَ كُلِّ شَےْءٍۖ حَتَّيٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذْنَٰهُم بَغْتَةٗ فَإِذَا هُم مُّبْلِسُونَۖ (45) فَقُطِعَ دَابِرُ اُ۬لْقَوْمِ اِ۬لذِينَ ظَلَمُواْۖ وَالْحَمْدُ لِلهِ رَبِّ اِ۬لْعَٰلَمِينَۖ (46) قُلَ اَرَٰٓيْتُمُۥٓ إِنَ اَخَذَ اَ۬للَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَيٰ قُلُوبِكُم مَّنِ اِلَٰهٌ غَيْرُ اُ۬للَّهِ يَاتِيكُم بِهِۖ اِ۟نظُرْ كَيْفَ نُصَرِّفُ اُ۬لَايَٰتِ ثُمَّ هُمْ يَصْدِفُونَۖ (47) قُلَ اَرَٰٓيْتَكُمُۥٓ إِنَ اَت۪يٰكُمْ عَذَابُ اُ۬للَّهِ بَغْتَةً اَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا اَ۬لْقَوْمُ اُ۬لظَّٰلِمُونَۖ (48) ۞وَمَا نُرْسِلُ اُ۬لْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۖ فَمَنَ اٰمَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۖ (49) وَالذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا يَمَسُّهُمُ اُ۬لْعَذَابُ بِمَا كَانُواْ يَفْسُقُونَۖ (50) قُل لَّآ أَقُولُ لَكُمْ عِندِے خَزَآئِنُ اُ۬للَّهِ وَلَآ أَعْلَمُ اُ۬لْغَيْبَ وَلَآ أَقُولُ لَكُمُۥٓ إِنِّے مَلَكٌۖ اِنَ اَتَّبِعُ إِلَّا مَا يُوح۪يٰٓ إِلَيَّۖ قُلْ هَلْ يَسْتَوِے اِ۬لَاعْم۪يٰ وَالْبَصِيرُۖ أَفَلَا تَتَفَكَّرُونَۖ (51) وَأَنذِرْ بِهِ اِ۬لذِينَ يَخَافُونَ أَنْ يُّحْشَرُوٓاْ إِلَيٰ رَبِّهِمْ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِيّٞ وَلَا شَفِيعٞ لَّعَلَّهُمْ يَتَّقُونَۖ (52) وَلَا تَطْرُدِ اِ۬لذِينَ يَدْعُونَ رَبَّهُم بِالْغَدَوٰةِ وَالْعَشِيِّ يُرِيدُونَ وَجْهَهُۥ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَےْءٖ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَےْءٖ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ اَ۬لظَّٰلِمِينَۖ (53) وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٖ لِّيَقُولُوٓاْ أَهَٰٓؤُلَآءِ مَنَّ اَ۬للَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآۖ أَلَيْسَ اَ۬للَّهُ بِأَعْلَمَ بِالشَّٰكِرِينَۖ (54) وَإِذَا جَآءَكَ اَ۬لذِينَ يُومِنُونَ بِـَٔايَٰتِنَا فَقُلْ سَلَٰمٌ عَلَيْكُمْۖ كَتَبَ رَبُّكُمْ عَلَيٰ نَفْسِهِ اِ۬لرَّحْمَةَ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءاَۢ بِجَهَٰلَةٖ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَإِنَّهُۥ غَفُورٞ رَّحِيمٞۖ (55) وَكَذَٰلِكَ نُفَصِّلُ اُ۬لَايَٰتِ وَلِتَسْتَبِينَ سَبِيلَ اَ۬لْمُجْرِمِينَۖ (56) قُلِ اِنِّے نُهِيتُ أَنَ اَعْبُدَ اَ۬لذِينَ تَدْعُونَ مِن دُونِ اِ۬للَّهِۖ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ قَد ضَّلَلْتُ إِذاٗ وَمَآ أَنَا مِنَ اَ۬لْمُهْتَدِينَۖ (57) قُلِ اِنِّے عَلَيٰ بَيِّنَةٖ مِّن رَّبِّے وَكَذَّبْتُم بِهِۦۖ مَا عِندِے مَا تَسْتَعْجِلُونَ بِهِۦٓۖ إِنِ اِ۬لْحُكْمُ إِلَّا لِلهِۖ يَقُصُّ اُ۬لْحَقَّۖ وَهُوَ خَيْرُ اُ۬لْفَٰصِلِينَۖ (58) قُل لَّوَ اَنَّ عِندِے مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِيَ اَ۬لَامْرُ بَيْنِے وَبَيْنَكُمْۖ وَاللَّهُ أَعْلَمُ بِالظَّٰلِمِينَۖ (59) ۞وَعِندَهُۥ مَفَاتِحُ اُ۬لْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَۖ وَيَعْلَمُ مَا فِے اِ۬لْبَرِّ وَالْبَحْرِۖ وَمَا تَسْقُطُ مِنْ وَّرَقَةٍ اِلَّا يَعْلَمُهَا وَلَا حَبَّةٖ فِے ظُلُمَٰتِ اِ۬لَارْضِ وَلَا رَطْبٖ وَلَا يَابِسٍ اِلَّا فِے كِتَٰبٖ مُّبِينٖۖ (60) وَهُوَ اَ۬لذِے يَتَوَفّ۪يٰكُم بِاليْلِ وَيَعْلَمُ مَا جَرَحْتُم بِالنَّه۪ارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْض۪يٰٓ أَجَلٞ مُّسَمّيٗۖ ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَۖ (61) وَهُوَ اَ۬لْقَاهِرُ فَوْقَ عِبَادِهِۦۖ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةًۖ حَتَّيٰٓ إِذَا جَآءَ احَدَكُمُ اُ۬لْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَۖ (62) ثُمَّ رُدُّوٓاْ إِلَي اَ۬للَّهِ مَوْل۪يٰهُمُ اُ۬لْحَقِّۖ أَلَا لَهُ اُ۬لْحُكْمُۖ وَهُوَ أَسْرَعُ اُ۬لْحَٰسِبِينَۖ (63) قُلْ مَنْ يُّنَجِّيكُم مِّن ظُلُمَٰتِ اِ۬لْبَرِّ وَالْبَحْرِ تَدْعُونَهُۥ تَضَرُّعاٗ وَخُفْيَةٗ لَّئِنَ اَنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ اَ۬لشَّٰكِرِينَۖ (64) قُلِ اِ۬للَّهُ يُنجِيكُم مِّنْهَا وَمِن كُلِّ كَرْبٖ ثُمَّ أَنتُمْ تُشْرِكُونَۖ (65) قُلْ هُوَ اَ۬لْقَادِرُ عَلَيٰٓ أَنْ يَّبْعَثَ عَلَيْكُمْ عَذَاباٗ مِّن فَوْقِكُمُۥٓ أَوْ مِن تَحْتِ أَرْجُلِكُمُۥٓ أَوْ يَلْبِسَكُمْ شِيَعاٗ وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍۖ اُ۟نظُرْ كَيْفَ نُصَرِّفُ اُ۬لَايَٰتِ لَعَلَّهُمْ يَفْقَهُونَۖ (66) وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ اَ۬لْحَقُّۖ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٖۖ لِّكُلِّ نَبَإٖ مُّسْتَقَرّٞۖ وَسَوْفَ تَعْلَمُونَۖ (67) وَإِذَا رَأَيْتَ اَ۬لذِينَ يَخُوضُونَ فِےٓ ءَايَٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّيٰ يَخُوضُواْ فِے حَدِيثٍ غَيْرِهِۦۖ وَإِمَّا يُنسِيَنَّكَ اَ۬لشَّيْطَٰنُ فَلَا تَقْعُدْ بَعْدَ اَ۬لذِّكْر۪يٰ مَعَ اَ۬لْقَوْمِ اِ۬لظَّٰلِمِينَۖ (68) وَمَا عَلَي اَ۬لذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَےْءٖ وَلَٰكِن ذِكْر۪يٰ لَعَلَّهُمْ يَتَّقُونَۖ (69) ۞وَذَرِ اِ۬لذِينَ اَ۪تَّخَذُواْ دِينَهُمْ لَعِباٗ وَلَهْواٗ وَغَرَّتْهُمُ اُ۬لْحَيَوٰةُ اُ۬لدُّنْي۪اۖ وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسُۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ اِ۬للَّهِ وَلِيّٞ وَلَا شَفِيعٞۖ وَإِن تَعْدِلْ كُلَّ عَدْلٖ لَّا يُوخَذْ مِنْهَاۖ أُوْلَٰٓئِكَ اَ۬لذِينَ أُبْسِلُواْ بِمَا كَسَبُواْۖ لَهُمْ شَرَابٞ مِّنْ حَمِيمٖ وَعَذَابٌ اَلِيمُۢ بِمَا كَانُواْ يَكْفُرُونَۖ (70) قُلَ اَنَدْعُواْ مِن دُونِ اِ۬للَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَيٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَد۪يٰنَا اَ۬للَّهُ كَالذِے اِ۪سْتَهْوَتْهُ اُ۬لشَّيَٰطِينُ فِے اِ۬لَارْضِ حَيْرَانَۖ لَهُۥٓ أَصْحَٰبٞ يَدْعُونَهُۥٓ إِلَي اَ۬لْهُدَي اَ۪يتِنَاۖ قُلِ اِنَّ هُدَي اَ۬للَّهِ هُوَ اَ۬لْهُد۪يٰۖ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ اِ۬لْعَٰلَمِينَ (71) وَأَنَ اَقِيمُواْ اُ۬لصَّلَوٰةَ وَاتَّقُوهُۖ وَهُوَ اَ۬لذِےٓ إِلَيْهِ تُحْشَرُونَۖ (72) وَهُوَ اَ۬لذِے خَلَقَ اَ۬لسَّمَٰوَٰتِ وَالَارْضَ بِالْحَقِّۖ وَيَوْمَ يَقُولُ كُن فَيَكُونُۖ (73) قَوْلُهُ اُ۬لْحَقُّۖ وَلَهُ اُ۬لْمُلْكُ يَوْمَ يُنفَخُ فِے اِ۬لصُّورِۖ عَٰلِمُ اُ۬لْغَيْبِ وَالشَّهَٰدَةِۖ وَهُوَ اَ۬لْحَكِيمُ اُ۬لْخَبِيرُۖ (74) وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَاماً اٰلِهَةًۖ اِنِّيَ أَر۪يٰكَ وَقَوْمَكَ فِے ضَلَٰلٖ مُّبِينٖۖ (75) وَكَذَٰلِكَ نُرِےٓ إِبْرَٰهِيمَ مَلَكُوتَ اَ۬لسَّمَٰوَٰتِ وَالَارْضِ وَلِيَكُونَ مِنَ اَ۬لْمُوقِنِينَۖ (76) فَلَمَّا جَنَّ عَلَيْهِ اِ۬ليْلُ ر۪ء۪ا كَوْكَباٗ قَالَ هَٰذَا رَبِّےۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ اُ۬لَافِلِينَۖ (77) فَلَمَّا رَءَا اَ۬لْقَمَرَ بَازِغاٗ قَالَ هَٰذَا رَبِّےۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِے رَبِّے لَأَكُونَنَّ مِنَ اَ۬لْقَوْمِ اِ۬لضَّآلِّينَۖ (78) فَلَمَّا رَءَا اَ۬لشَّمْسَ بَازِغَةٗ قَالَ هَٰذَا رَبِّے هَٰذَآ أَكْبَرُۖ فَلَمَّآ أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّے بَرِےٓءٞ مِّمَّا تُشْرِكُونَۖ (79) إِنِّے وَجَّهْتُ وَجْهِيَ لِلذِے فَطَرَ اَ۬لسَّمَٰوَٰتِ وَالَارْضَ حَنِيفاٗۖ وَمَآ أَنَا مِنَ اَ۬لْمُشْرِكِينَۖ (80) ۞وَحَآجَّهُۥ قَوْمُهُۥۖ قَالَ أَتُحَٰٓجُّونِے فِے اِ۬للَّهِ وَقَدْ هَد۪يٰنِۖ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَنْ يَّشَآءَ رَبِّے شَيْـٔاٗۖ وَسِعَ رَبِّے كُلَّ شَےْءٍ عِلْماًۖ اَفَلَا تَتَذَكَّرُونَۖ (81) وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمُۥٓ أَشْرَكْتُم بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَٰناٗۖ فَأَيُّ اُ۬لْفَرِيقَيْنِ أَحَقُّ بِالَامْنِ إِن كُنتُمْ تَعْلَمُونَۖ (82) اَ۬لذِينَ ءَامَنُواْ وَلَمْ يَلْبِسُوٓاْ إِيمَٰنَهُم بِظُلْمٍ ا۟وْلَٰٓئِكَ لَهُمُ اُ۬لَامْنُ وَهُم مُّهْتَدُونَۖ (83) وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَٰهَآ إِبْرَٰهِيمَ عَلَيٰ قَوْمِهِۦۖ نَرْفَعُ دَرَجَٰتِ مَن نَّشَآءُۖ اِ۪نَّ رَبَّكَ حَكِيمٌ عَلِيمٞۖ (84) وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَۖ كُلّاً هَدَيْنَاۖ وَنُوحاً هَدَيْنَا مِن قَبْلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوس۪يٰ وَهَٰرُونَۖ وَكَذَٰلِكَ نَجْزِے اِ۬لْمُحْسِنِينَۖ (85) وَزَكَرِيَّآءَ وَيَحْي۪يٰ وَعِيس۪يٰ وَإِلْيَاسَۖ كُلّٞ مِّنَ اَ۬لصَّٰلِحِينَۖ (86) وَإِسْمَٰعِيلَ وَالْيَسَعَ وَيُونُسَ وَلُوطاٗۖ وَكُلّاٗ فَضَّلْنَا عَلَي اَ۬لْعَٰلَمِينَۖ (87) وَمِنَ اٰبَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْۖ وَاجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمُۥٓ إِلَيٰ صِرَٰطٖ مُّسْتَقِيمٖۖ (88) ذَٰلِكَ هُدَي اَ۬للَّهِ يَهْدِے بِهِۦ مَنْ يَّشَآءُ مِنْ عِبَادِهِۦۖ وَلَوَ اَشْرَكُواْ لَحَبِطَ عَنْهُم مَّا كَانُواْ يَعْمَلُونَۖ (89) أُوْلَٰٓئِكَ اَ۬لذِينَ ءَاتَيْنَٰهُمُ اُ۬لْكِتَٰبَ وَالْحُكْمَ وَالنُّبُوٓءَةَۖ فَإِنْ يَّكْفُرْ بِهَا هَٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْماٗ لَّيْسُواْ بِهَا بِكٰ۪فِرِينَۖ (90) أُوْلَٰٓئِكَ اَ۬لذِينَ هَدَي اَ۬للَّهُ فَبِهُد۪يٰهُمُ اُ۪قْتَدِهْۖ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْراًۖ اِنْ هُوَ إِلَّا ذِكْر۪يٰ لِلْعَٰلَمِينَۖ (91) ۞وَمَا قَدَرُواْ اُ۬للَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُواْ مَآ أَنزَلَ اَ۬للَّهُ عَلَيٰ بَشَرٖ مِّن شَےْءٖۖ قُلْ مَنَ اَنزَلَ اَ۬لْكِتَٰبَ اَ۬لذِے جَآءَ بِهِۦ مُوس۪يٰ نُوراٗ وَهُديٗ لِّلنَّاسِ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيراٗۖ وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓاْ أَنتُمْ وَلَآ ءَابَآؤُكُمْ قُلِ اِ۬للَّهُۖ ثُمَّ ذَرْهُمْ فِے خَوْضِهِمْ يَلْعَبُونَۖ (92) وَهَٰذَا كِتَٰبٌ اَنزَلْنَٰهُ مُبَٰرَكٞ مُّصَدِّقُ اُ۬لذِے بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ اَ۬لْقُر۪يٰ وَمَنْ حَوْلَهَاۖ وَالذِينَ يُومِنُونَ بِالَاخِرَةِ يُومِنُونَ بِهِۦ وَهُمْ عَلَيٰ صَلَاتِهِمْ يُحَافِظُونَۖ (93) وَمَنَ اَظْلَمُ مِمَّنِ اِ۪فْتَر۪يٰ عَلَي اَ۬للَّهِ كَذِباً اَوْ قَالَ أُوحِيَ إِلَيَّ وَلَمْ يُوحَ إِلَيْهِ شَےْءٞ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ اَ۬للَّهُۖ وَلَوْ تَر۪يٰٓ إِذِ اِ۬لظَّٰلِمُونَ فِے غَمَرَٰتِ اِ۬لْمَوْتِ وَالْمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيْدِيهِمُۥٓ أَخْرِجُوٓاْ أَنفُسَكُمُۖ اُ۬لْيَوْمَ تُجْزَوْنَ عَذَابَ اَ۬لْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَي اَ۬للَّهِ غَيْرَ اَ۬لْحَقِّ وَكُنتُمْ عَنَ اٰيَٰتِهِۦ تَسْتَكْبِرُونَۖ (94) وَلَقَدْ جِئْتُمُونَا فُرَٰد۪يٰ كَمَا خَلَقْنَٰكُمُۥٓ أَوَّلَ مَرَّةٖ وَتَرَكْتُم مَّا خَوَّلْنَٰكُمْ وَرَآءَ ظُهُورِكُمْۖ وَمَا نَر۪يٰ مَعَكُمْ شُفَعَآءَكُمُ اُ۬لذِينَ زَعَمْتُمُۥٓ أَنَّهُمْ فِيكُمْ شُرَكَٰٓؤُاْۖ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَۖ (95) ۞إِنَّ اَ۬للَّهَ فَٰلِقُ اُ۬لْحَبِّ وَالنَّو۪يٰۖ يُخْرِجُ اُ۬لْحَيَّ مِنَ اَ۬لْمَيِّتِ وَمُخْرِجُ اُ۬لْمَيِّتِ مِنَ اَ۬لْحَيِّۖ ذَٰلِكُمُ اُ۬للَّهُۖ فَأَنّ۪يٰ تُوفَكُونَۖ (96) فَالِقُ اُ۬لِاصْبَاحِ وَجَٰعِلُ اُ۬ليْلِ سَكَناٗ وَالشَّمْسَ وَالْقَمَرَ حُسْبَٰناٗۖ ذَٰلِكَ تَقْدِيرُ اُ۬لْعَزِيزِ اِ۬لْعَلِيمِۖ (97) وَهُوَ اَ۬لذِے جَعَلَ لَكُمُ اُ۬لنُّجُومَ لِتَهْتَدُواْ بِهَا فِے ظُلُمَٰتِ اِ۬لْبَرِّ وَالْبَحْرِۖ قَدْ فَصَّلْنَا اَ۬لَايَٰتِ لِقَوْمٖ يَعْلَمُونَۖ (98) وَهُوَ اَ۬لذِےٓ أَنشَأَكُم مِّن نَّفْسٖ وَٰحِدَةٖ فَمُسْتَقَرّٞ وَمُسْتَوْدَعٞۖ قَدْ فَصَّلْنَا اَ۬لَايَٰتِ لِقَوْمٖ يَفْقَهُونَۖ (99) وَهُوَ اَ۬لذِےٓ أَنزَلَ مِنَ اَ۬لسَّمَآءِ مَآءٗ فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَےْءٖ فَأَخْرَجْنَا مِنْهُ خَضِراٗ نُّخْرِجُ مِنْهُ حَبّاٗ مُّتَرَاكِباٗ وَمِنَ اَ۬لنَّخْلِ مِن طَلْعِهَا قِنْوَانٞ دَانِيَةٞ وَجَنَّٰتٖ مِّنَ اَعْنَٰبٖ وَالزَّيْتُونَ وَالرُّمَّانَ مُشْتَبِهاٗ وَغَيْرَ مُتَشَٰبِهٍۖ اُ۟نظُرُوٓاْ إِلَيٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓۖ إِنَّ فِے ذَٰلِكُمْ لَأٓيَٰتٖ لِّقَوْمٖ يُومِنُونَۖ (100) وَجَعَلُواْ لِلهِ شُرَكَآءَ اَ۬لْجِنَّ وَخَلَقَهُمْۖ وَخَرَّقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۢ بِغَيْرِ عِلْمٖۖ سُبْحَٰنَهُۥ وَتَعَٰل۪يٰ عَمَّا يَصِفُونَۖ (101) بَدِيعُ اُ۬لسَّمَٰوَٰتِ وَالَارْضِۖ أَنّ۪يٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمْ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَےْءٖۖ وَهُوَ بِكُلِّ شَےْءٍ عَلِيمٞۖ (102) ذَٰلِكُمُ اُ۬للَّهُ رَبُّكُمْۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَےْءٖ فَاعْبُدُوهُۖ وَهُوَ عَلَيٰ كُلِّ شَےْءٖ وَكِيلٞۖ (103) ۞لَّا تُدْرِكُهُ اُ۬لَابْصَٰرُ وَهُوَ يُدْرِكُ اُ۬لَابْصَٰرَۖ وَهُوَ اَ۬للَّطِيفُ اُ۬لْخَبِيرُۖ (104) قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْۖ فَمَنَ اَبْصَرَ فَلِنَفْسِهِۦۖ وَمَنْ عَمِيَ فَعَلَيْهَاۖ وَمَآ أَنَا عَلَيْكُم بِحَفِيظٖۖ (105) وَكَذَٰلِكَ نُصَرِّفُ اُ۬لَايَٰتِ وَلِيَقُولُواْ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٖ يَعْلَمُونَۖ (106) اَ۪تَّبِعْ مَآ أُوحِيَ إِلَيْكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعْرِضْ عَنِ اِ۬لْمُشْرِكِينَۖ (107) وَلَوْ شَآءَ اَ۬للَّهُ مَآ أَشْرَكُواْۖ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظاٗۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٖۖ (108) وَلَا تَسُبُّواْ اُ۬لذِينَ يَدْعُونَ مِن دُونِ اِ۬للَّهِ فَيَسُبُّواْ اُ۬للَّهَ عَدْواَۢ بِغَيْرِ عِلْمٖۖ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْۖ ثُمَّ إِلَيٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعْمَلُونَۖ (109) وَأَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَتْهُمُۥٓ ءَايَةٞ لَّيُومِنُنَّ بِهَاۖ قُلِ اِنَّمَا اَ۬لَايَٰتُ عِندَ اَ۬للَّهِۖ وَمَا يُشْعِرُكُمُۥٓ أَنَّهَآ إِذَا جَآءَتْ لَا يُومِنُونَۖ (110) وَنُقَلِّبُ أَفْـِٕدَتَهُمْ وَأَبْصَٰرَهُمْ كَمَا لَمْ يُومِنُواْ بِهِۦٓ أَوَّلَ مَرَّةٖ وَنَذَرُهُمْ فِے طُغْيَٰنِهِمْ يَعْمَهُونَۖ (111) ۞وَلَوَ اَنَّنَا نَزَّلْنَآ إِلَيْهِمُ اُ۬لْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ اُ۬لْمَوْت۪يٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَےْءٖ قِبَلاٗ مَّا كَانُواْ لِيُومِنُوٓاْ إِلَّآ أَنْ يَّشَآءَ اَ۬للَّهُ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَۖ (112) وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِےٓءٍ عَدُوّاٗ شَيَٰطِينَ اَ۬لِانسِ وَالْجِنِّ يُوحِے بَعْضُهُمُۥٓ إِلَيٰ بَعْضٖ زُخْرُفَ اَ۬لْقَوْلِ غُرُوراٗۖ وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرْهُمْ وَمَا يَفْتَرُونَۖ (113) وَلِتَصْغ۪يٰٓ إِلَيْهِ أَفْـِٕدَةُ اُ۬لذِينَ لَا يُومِنُونَ بِالَاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُواْ مَا هُم مُّقْتَرِفُونَۖ (114) أَفَغَيْرَ اَ۬للَّهِ أَبْتَغِے حَكَماٗ وَهُوَ اَ۬لذِےٓ أَنزَلَ إِلَيْكُمُ اُ۬لْكِتَٰبَ مُفَصَّلاٗۖ وَالذِينَ ءَاتَيْنَٰهُمُ اُ۬لْكِتَٰبَ يَعْلَمُونَ أَنَّهُۥ مُنزَلٞ مِّن رَّبِّكَ بِالْحَقِّۖ فَلَا تَكُونَنَّ مِنَ اَ۬لْمُمْتَرِينَۖ (115) وَتَمَّتْ كَلِمَٰتُ رَبِّكَ صِدْقاٗ وَعَدْلاٗۖ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۖ وَهُوَ اَ۬لسَّمِيعُ اُ۬لْعَلِيمُۖ (116) وَإِن تُطِعَ اَكْثَرَ مَن فِے اِ۬لَارْضِ يُضِلُّوكَ عَن سَبِيلِ اِ۬للَّهِۖ إِنْ يَّتَّبِعُونَ إِلَّا اَ۬لظَّنَّ وَإِنْ هُمُۥٓ إِلَّا يَخْرُصُونَۖ (117) إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَنْ يَّضِلُّ عَن سَبِيلِهِۦۖ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَۖ (118) فَكُلُواْ مِمَّا ذُكِرَ اَ۪سْمُ اُ۬للَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُومِنِينَۖ (119) وَمَا لَكُمُۥٓ أَلَّا تَاكُلُواْ مِمَّا ذُكِرَ اَ۪سْمُ اُ۬للَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمُۥٓ إِلَّا مَا اَ۟ضْطُرِرْتُمُۥٓ إِلَيْهِۖ وَإِنَّ كَثِيراٗ لَّيَضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍۖ اِنَّ رَبَّكَ هُوَ أَعْلَمُ بِالْمُعْتَدِينَۖ (120) ۞وَذَرُواْ ظَٰهِرَ اَ۬لِاثْمِ وَبَاطِنَهُۥٓۖ إِنَّ اَ۬لذِينَ يَكْسِبُونَ اَ۬لِاثْمَ سَيُجْزَوْنَ بِمَا كَانُواْ يَقْتَرِفُونَۖ (121) وَلَا تَاكُلُواْ مِمَّا لَمْ يُذْكَرِ اِ۪سْمُ اُ۬للَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٞۖ وَإِنَّ اَ۬لشَّيَٰطِينَ لَيُوحُونَ إِلَيٰٓ أَوْلِيَآئِهِمْ لِيُجَٰدِلُوكُمْۖ وَإِنَ اَطَعْتُمُوهُمُۥٓ إِنَّكُمْ لَمُشْرِكُونَۖ (122) أَوَمَن كَانَ مَيِّتاٗ فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُوراٗ يَمْشِے بِهِۦ فِے اِ۬لنَّاسِ كَمَن مَّثَلُهُۥ فِے اِ۬لظُّلُمَٰتِ لَيْسَ بِخَارِجٖ مِّنْهَاۖ كَذَٰلِكَ زُيِّنَ لِلْكٰ۪فِرِينَ مَا كَانُواْ يَعْمَلُونَۖ (123) وَكَذَٰلِكَ جَعَلْنَا فِے كُلِّ قَرْيَةٍ اَكَٰبِرَ مُجْرِمِيهَا لِيَمْكُرُواْ فِيهَاۖ وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَۖ (124) وَإِذَا جَآءَتْهُمُۥٓ ءَايَةٞ قَالُواْ لَن نُّومِنَ حَتَّيٰ نُوت۪يٰ مِثْلَ مَآ أُوتِيَ رُسُلُ اُ۬للَّهِۖ اِ۬للَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَٰلَٰتِهِۦۖ سَيُصِيبُ اُ۬لذِينَ أَجْرَمُواْ صَغَارٌ عِندَ اَ۬للَّهِ وَعَذَابٞ شَدِيدُۢ بِمَا كَانُواْ يَمْكُرُونَۖ (125) فَمَنْ يُّرِدِ اِ۬للَّهُ أَنْ يَّهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلِاسْلَٰمِۖ وَمَنْ يُّرِدَ اَنْ يُّضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقاً حَرِجاٗ كَأَنَّمَا يَصَّعَّدُ فِے اِ۬لسَّمَآءِۖ كَذَٰلِكَ يَجْعَلُ اُ۬للَّهُ اُ۬لرِّجْسَ عَلَي اَ۬لذِينَ لَا يُومِنُونَۖ (126) وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيماٗۖ قَدْ فَصَّلْنَا اَ۬لَايَٰتِ لِقَوْمٖ يَذَّكَّرُونَۖ (127) ۞لَهُمْ دَارُ اُ۬لسَّلَٰمِ عِندَ رَبِّهِمْۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعْمَلُونَۖ (128) وَيَوْمَ نَحْشُرُهُمْ جَمِيعاٗ يَٰمَعْشَرَ اَ۬لْجِنِّ قَدِ اِ۪سْتَكْثَرْتُم مِّنَ اَ۬لِانسِۖ وَقَالَ أَوْلِيَآؤُهُم مِّنَ اَ۬لِانسِ رَبَّنَا اَ۪سْتَمْتَعَ بَعْضُنَا بِبَعْضٖ وَبَلَغْنَآ أَجَلَنَا اَ۬لذِےٓ أَجَّلْتَ لَنَاۖ قَالَ اَ۬لنَّارُ مَثْو۪يٰكُمْ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ اَ۬للَّهُۖ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞۖ (129) وَكَذَٰلِكَ نُوَلِّے بَعْضَ اَ۬لظَّٰلِمِينَ بَعْضاَۢ بِمَا كَانُواْ يَكْسِبُونَۖ (130) يَٰمَعْشَرَ اَ۬لْجِنِّ وَالِانسِ أَلَمْ يَاتِكُمْ رُسُلٞ مِّنكُمْ يَقُصُّونَ عَلَيْكُمُۥٓ ءَايَٰتِے وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَاۖ قَالُواْ شَهِدْنَا عَلَيٰٓ أَنفُسِنَاۖ وَغَرَّتْهُمُ اُ۬لْحَيَوٰةُ اُ۬لدُّنْي۪ا وَشَهِدُواْ عَلَيٰٓ أَنفُسِهِمُۥٓ أَنَّهُمْ كَانُواْ كٰ۪فِرِينَۖ (131) ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ اَ۬لْقُر۪يٰ بِظُلْمٖ وَأَهْلُهَا غَٰفِلُونَۖ (132) وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۖ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَۖ (133) وَرَبُّكَ اَ۬لْغَنِيُّ ذُو اُ۬لرَّحْمَةِۖ إِنْ يَّشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ اٰخَرِينَۖ (134) إِنَّ مَا تُوعَدُونَ لَأٓتٖۖ وَمَآ أَنتُم بِمُعْجِزِينَۖ (135) ۞قُلْ يَٰقَوْمِ اِ۪عْمَلُواْ عَلَيٰ مَكَانَتِكُمُۥٓ إِنِّے عَامِلٞۖ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ اُ۬لدّ۪ارِۖ إِنَّهُۥ لَا يُفْلِحُ اُ۬لظَّٰلِمُونَۖ (136) وَجَعَلُواْ لِلهِ مِمَّا ذَرَأَ مِنَ اَ۬لْحَرْثِ وَالَانْعَٰمِ نَصِيباٗ فَقَالُواْ هَٰذَا لِلهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَي اَ۬للَّهِۖ وَمَا كَانَ لِلهِ فَهُوَ يَصِلُ إِلَيٰ شُرَكَآئِهِمْۖ سَآءَ مَا يَحْكُمُونَۖ (137) وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ اَ۬لْمُشْرِكِينَ قَتْلَ أَوْلَٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُواْ عَلَيْهِمْ دِينَهُمْۖ وَلَوْ شَآءَ اَ۬للَّهُ مَا فَعَلُوهُۖ فَذَرْهُمْ وَمَا يَفْتَرُونَۖ (138) وَقَالُواْ هَٰذِهِۦٓ أَنْعَٰمٞ وَحَرْثٌ حِجْرٞ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَٰمٌ حُرِّمَت ظُّهُورُهَا وَأَنْعَٰمٞ لَّا يَذْكُرُونَ اَ۪سْمَ اَ۬للَّهِ عَلَيْهَا اَ۪فْتِرَآءً عَلَيْهِۖ سَيَجْزِيهِم بِمَا كَانُواْ يَفْتَرُونَۖ (139) وَقَالُواْ مَا فِے بُطُونِ هَٰذِهِ اِ۬لَانْعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَيٰٓ أَزْوَٰجِنَاۖ وَإِنْ يَّكُن مَّيْتَةٗ فَهُمْ فِيهِ شُرَكَآءُۖ سَيَجْزِيهِمْ وَصْفَهُمُۥٓۖ إِنَّهُۥ حَكِيمٌ عَلِيمٞۖ (140) ۞قَدْ خَسِرَ اَ۬لذِينَ قَتَلُوٓاْ أَوْلَٰدَهُمْ سَفَهاَۢ بِغَيْرِ عِلْمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ اُ۬للَّهُ اُ۪فْتِرَآءً عَلَي اَ۬للَّهِۖ قَد ضَّلُّواْ وَمَا كَانُواْ مُهْتَدِينَۖ (141) وَهُوَ اَ۬لذِےٓ أَنشَأَ جَنَّٰتٖ مَّعْرُوشَٰتٖ وَغَيْرَ مَعْرُوشَٰتٖ وَالنَّخْلَ وَالزَّرْعَ مُخْتَلِفاً ا۟كْلُهُۥۖ وَالزَّيْتُونَ وَالرُّمَّانَ مُتَشَٰبِهاٗ وَغَيْرَ مُتَشَٰبِهٖۖ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُواْ حَقَّهُۥ يَوْمَ حِصَادِهِۦۖ وَلَا تُسْرِفُوٓاْۖ إِنَّهُۥ لَا يُحِبُّ اُ۬لْمُسْرِفِينَۖ (142) وَمِنَ اَ۬لَانْعَٰمِ حَمُولَةٗ وَفَرْشاٗۖ كُلُواْ مِمَّا رَزَقَكُمُ اُ۬للَّهُ وَلَا تَتَّبِعُواْ خُطْوَٰتِ اِ۬لشَّيْطَٰنِۖ إِنَّهُۥ لَكُمْ عَدُوّٞ مُّبِينٞۖ (143) ثَمَٰنِيَةَ أَزْوَٰجٖۖ مِّنَ اَ۬لضَّأْنِ اِ۪ثْنَيْنِ وَمِنَ اَ۬لْمَعْزِ اِ۪ثْنَيْنِۖ قُلَ آٰلذَّكَرَيْنِ حَرَّمَ أَمِ اِ۬لُانثَيَيْنِ أَمَّا اَ۪شْتَمَلَتْ عَلَيْهِ أَرْحَامُ اُ۬لُانثَيَيْنِۖ نَبِّـُٔونِے بِعِلْمٍ اِن كُنتُمْ صَٰدِقِينَۖ (144) وَمِنَ اَ۬لِابِلِ اِ۪ثْنَيْنِ وَمِنَ اَ۬لْبَقَرِ اِ۪ثْنَيْنِۖ قُلَ آٰلذَّكَرَيْنِ حَرَّمَ أَمِ اِ۬لُانثَيَيْنِ أَمَّا اَ۪شْتَمَلَتْ عَلَيْهِ أَرْحَامُ اُ۬لُانثَيَيْنِۖ أَمْ كُنتُمْ شُهَدَآءَ ا۪ذْ وَصّ۪يٰكُمُ اُ۬للَّهُ بِهَٰذَاۖ فَمَنَ اَظْلَمُ مِمَّنِ اِ۪فْتَر۪يٰ عَلَي اَ۬للَّهِ كَذِباٗ لِّيُضِلَّ اَ۬لنَّاسَ بِغَيْرِ عِلْمٍۖ اِنَّ اَ۬للَّهَ لَا يَهْدِے اِ۬لْقَوْمَ اَ۬لظَّٰلِمِينَۖ (145) ۞قُل لَّآ أَجِدُ فِے مَآ أُوحِيَ إِلَيَّ مُحَرَّماً عَلَيٰ طَاعِمٖ يَطْعَمُهُۥٓ إِلَّآ أَنْ يَّكُونَ مَيْتَةً اَوْ دَماٗ مَّسْفُوحاً اَوْ لَحْمَ خِنزِيرٖ فَإِنَّهُۥ رِجْسٌ اَوْ فِسْقاً ا۟هِلَّ لِغَيْرِ اِ۬للَّهِ بِهِۦۖ فَمَنُ اُ۟ضْطُرَّ غَيْرَ بَاغٖ وَلَا عَادٖ فَإِنَّ رَبَّكَ غَفُورٞ رَّحِيمٞۖ (146) وَعَلَي اَ۬لذِينَ هَادُواْ حَرَّمْنَا كُلَّ ذِے ظُفُرٖۖ وَمِنَ اَ۬لْبَقَرِ وَالْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَت ظُّهُورُهُمَآ أَوِ اِ۬لْحَوَاي۪آ أَوْ مَا اَ۪خْتَلَطَ بِعَظْمٖۖ ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْۖ وَإِنَّا لَصَٰدِقُونَۖ (147) فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٖ وَٰسِعَةٖۖ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ اِ۬لْقَوْمِ اِ۬لْمُجْرِمِينَۖ (148) سَيَقُولُ اُ۬لذِينَ أَشْرَكُواْ لَوْ شَآءَ اَ۬للَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَےْءٖۖ كَذَٰلِكَ كَذَّبَ اَ۬لذِينَ مِن قَبْلِهِمْ حَتَّيٰ ذَاقُواْ بَأْسَنَاۖ قُلْ هَلْ عِندَكُم مِّنْ عِلْمٖ فَتُخْرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا اَ۬لظَّنَّ وَإِنَ اَنتُمُۥٓ إِلَّا تَخْرُصُونَۖ (149) قُلْ فَلِلهِ اِ۬لْحُجَّةُ اُ۬لْبَٰلِغَةُۖ فَلَوْ شَآءَ لَهَد۪يٰكُمُۥٓ أَجْمَعِينَۖ (150) قُلْ هَلُمَّ شُهَدَآءَكُمُ اُ۬لذِينَ يَشْهَدُونَ أَنَّ اَ۬للَّهَ حَرَّمَ هَٰذَاۖ فَإِن شَهِدُواْ فَلَا تَشْهَدْ مَعَهُمْۖ وَلَا تَتَّبِعَ اَهْوَآءَ اَ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَالذِينَ لَا يُومِنُونَ بِالَاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ (151) ۞قُلْ تَعَالَوَاْ اَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمُۥٓۖ أَلَّا تُشْرِكُواْ بِهِۦ شَيْـٔاٗ وَبِالْوَٰلِدَيْنِ إِحْسَٰناٗۖ وَلَا تَقْتُلُوٓاْ أَوْلَٰدَكُم مِّنِ اِمْلَٰقٖۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْۖ وَلَا تَقْرَبُواْ اُ۬لْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَۖ وَلَا تَقْتُلُواْ اُ۬لنَّفْسَ اَ۬لتِے حَرَّمَ اَ۬للَّهُ إِلَّا بِالْحَقِّۖ ذَٰلِكُمْ وَصّ۪يٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَۖ (152) وَلَا تَقْرَبُواْ مَالَ اَ۬لْيَتِيمِ إِلَّا بِالتِے هِيَ أَحْسَنُ حَتَّيٰ يَبْلُغَ أَشُدَّهُۥۖ وَأَوْفُواْ اُ۬لْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِۖ لَا نُكَلِّفُ نَفْساً اِلَّا وُسْعَهَاۖ وَإِذَا قُلْتُمْ فَاعْدِلُواْ وَلَوْ كَانَ ذَا قُرْب۪يٰۖ وَبِعَهْدِ اِ۬للَّهِ أَوْفُواْۖ ذَٰلِكُمْ وَصّ۪يٰكُم بِهِۦ لَعَلَّكُمْ تَذَّكَّرُونَۖ (153) وَأَنَّ هَٰذَا صِرَٰطِے مُسْتَقِيماٗ فَاتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ اُ۬لسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦۖ ذَٰلِكُمْ وَصّ۪يٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَۖ (154) ثُمَّ ءَاتَيْنَا مُوسَي اَ۬لْكِتَٰبَ تَمَاماً عَلَي اَ۬لذِےٓ أَحْسَنَ وَتَفْصِيلاٗ لِّكُلِّ شَےْءٖ وَهُديٗ وَرَحْمَةٗ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُومِنُونَۖ (155) وَهَٰذَا كِتَٰبٌ اَنزَلْنَٰهُ مُبَٰرَكٞ فَاتَّبِعُوهُ وَاتَّقُواْ لَعَلَّكُمْ تُرْحَمُونَ (156) أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ اَ۬لْكِتَٰبُ عَلَيٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَٰفِلِينَ (157) أَوْ تَقُولُواْ لَوَ اَنَّآ أُنزِلَ عَلَيْنَا اَ۬لْكِتَٰبُ لَكُنَّآ أَهْد۪يٰ مِنْهُمْۖ فَقَدْ جَآءَكُم بَيِّنَةٞ مِّن رَّبِّكُمْ وَهُديٗ وَرَحْمَةٞۖ فَمَنَ اَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ اِ۬للَّهِ وَصَدَفَ عَنْهَاۖ سَنَجْزِے اِ۬لذِينَ يَصْدِفُونَ عَنَ اٰيَٰتِنَا سُوٓءَ اَ۬لْعَذَابِ بِمَا كَانُواْ يَصْدِفُونَۖ (158) ۞هَلْ يَنظُرُونَ إِلَّآ أَن تَاتِيَهُمُ اُ۬لْمَلَٰٓئِكَةُ أَوْ يَاتِيَ رَبُّكَ أَوْ يَاتِيَ بَعْضُ ءَايَٰتِ رَبِّكَۖ يَوْمَ يَاتِے بَعْضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفْساً اِيمَٰنُهَا لَمْ تَكُنَ اٰمَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِےٓ إِيمَٰنِهَا خَيْراٗۖ قُلِ اِ۪نتَظِرُوٓاْ إِنَّا مُنتَظِرُونَۖ (159) إِنَّ اَ۬لذِينَ فَرَّقُواْ دِينَهُمْ وَكَانُواْ شِيَعاٗ لَّسْتَ مِنْهُمْ فِے شَےْءٍۖ اِنَّمَآ أَمْرُهُمُۥٓ إِلَي اَ۬للَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفْعَلُونَۖ (160) مَن جَآءَ بِالْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَاۖ وَمَن جَآءَ بِالسَّيِّئَةِ فَلَا يُجْز۪يٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَۖ (161) قُلِ اِنَّنِے هَد۪يٰنِے رَبِّيَ إِلَيٰ صِرَٰطٖ مُّسْتَقِيمٖۖ (162) دِيناٗ قَيِّماٗ مِّلَّةَ إِبْرَٰهِيمَ حَنِيفاٗۖ وَمَا كَانَ مِنَ اَ۬لْمُشْرِكِينَۖ (163) قُلِ اِنَّ صَلَاتِے وَنُسُكِے وَمَحْي۪آےْ وَمَمَاتِيَ لِلهِ رَبِّ اِ۬لْعَٰلَمِينَ (164) لَا شَرِيكَ لَهُۥۖ وَبِذَٰلِكَ أُمِرْتُۖ وَأَنَآ أَوَّلُ اُ۬لْمُسْلِمِينَۖ (165) قُلَ اَغَيْرَ اَ۬للَّهِ أَبْغِے رَبّاٗ وَهُوَ رَبُّ كُلِّ شَےْءٖۖ وَلَا تَكْسِبُ كُلُّ نَفْسٍ اِلَّا عَلَيْهَاۖ وَلَا تَزِرُ وَازِرَةٞ وِزْرَ أُخْر۪يٰۖ ثُمَّ إِلَيٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَۖ (166) وَهُوَ اَ۬لذِے جَعَلَكُمْ خَلَٰٓئِفَ اَ۬لَارْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٖ دَرَجَٰتٖ لِّيَبْلُوَكُمْ فِے مَآ ءَات۪يٰكُمُۥٓۖ إِنَّ رَبَّكَ سَرِيعُ اُ۬لْعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمٌۖ (167)
',
